	TITLE 'sf.asm'*********************************************************************** Standard File, version 2	** Created:		6/01/1988***             Copyright (c) Apple Computer, Inc. 1988-1992*	       All Rights Reserved** Ideas from original Standard File but all code has been rewritten* from the ground up. The code now makes use of system tools which were* not available at the first writing of standard file. Additional tool* calls to support GS/OS have been added.**  7/01/88 - Got new dialog routines written*  7/25/88 - Completed interface to the list manager*  8/01/88 - Completed mamory management calls to build file data*  8/08/88 - Completed building list of file names for a folder*  8/16/88 - Custom draw routine for file names added*  8/22/88 - Completed code to move up and down folder levels.*  8/29/88 - Corrections to memory allocation problems.*  9/02/88 - Added code for path name display *  9/03/88 - Completed code for custom display of path name and extra long names.*  9/05/88 - Added icons to path names and file name displays*  9/09/88 - Break to write 0.1 through 0.3 ERS*  9/19/88 - Added code for button highlites and flashing.*  9/21/88 - Complete button highlights and interaction with other dialog parts.*  9/23/88 - Start code for volume switch. (and documentation update)*  9/27/88 - Volume button works. Beginning debug on all code.*  9/27/88 - Adding new icons for devices!*  9/28/88 - Add color to icons. Start support for AppleShare (privilege voilations)*  9/30/88 - Select first list element, button highlight control, prefix "juggling".* 10/03/88 - Start on Put Dialog and associated code.* 10/07/88 - Start re-write on ERS.* 10/09/88 - Start code on moving dialog into allocated memory. (have to MUNG old dialog formats)* 10/12/88 - Completed all above. Add grey out list items.* 10/13/88 - Re-write code for open button disable/enable (based on greyed out item code)* 10/15/88 - Add code to handle key equiv. Fix calls into tools.* 10/20/88 - Add code for save and New Folder button highlight* 10/24/88 - Add New Folder code and error alerts.* 10/27/88 - Cleanup and add entries for main calls* 10/28/88 - Add fliterProc hooks and TypeList checking (old style)* 11/02/88 - Fix Open/Close bug on folders (caused eventual crash)* 11/05/88 - General fixes. Correct custom template bug.* 11/09/88 - Start on building Reply Record. Fix some items from code review.* 11/11/88 - Continue debugging as tool. Add code for file replacement for existing files.* 11/28/88 - Add code to support new type lists.* 11/29/88 - Change TRUE to $FFFF. Change input parameters to conform to ERS 0.7* 12/01/88 - Clean up code. Add entry error checking.* 12/09/88 - Fix 320 die error. Remove QDAux calls for icons. (changed to PPtoPort)* 12/13/88 - Add new call: SFRescan to allow the list to be redrawn with new filters and procs.* 12/15/88 - Begin multifile selection support* 12/17/88 - stop above, begin debug cycle.*  1/08/89 - start multifile (again)*  1/20/89 - complete multifile (first pass)*  1/23/89 - remove Alert windows and replace with ErrorWindow calls.*  1/25/89 - Save button status change. No save or folder to write protected disks.*  1/27/89 - Added a locked icon to the pathname display for write disabled disks.*  2/09/89 - Check in misc fixes for bugs reported:*	PutFile modes failed on nil OrigNameStr*	bit# instruction was missing # on an instruction causing strange error*	edit field max length error on new PutFile calls*  2/10/89 - Add hook to allow Claris to modify the icon for each file displayed*  4/28/89 - Fix DTS reported bugs with in old calls. 1). Status did not return high bit set.*	2). ':' instead of '/' were returned in path names.*	3). First character in file name being blasted in old filter proc records.* 5/15/89 - Fix reported bugs: 1). 320 Get dialog was incorrect and has been corrected.*	2). The New Reply record contained false File and Aux types. This is fixed.*	3). The Multi Reply Record had incorrect File and Aux types. This is fixed.* 5/17/89 - Yet more fixes: 1). Save & Folder button sometimes light even if string is empty. Fixed.*	2). Releasing of resources was done incorrectly which caused the prompt*	    string to display incorrectly on subsequent calls. Fixed.*	3). New calls default name didn't show up. Fixed*	4). Pressing CR or ENTER if the save field was empty caused the char*	    to be put into the Line text field. Fixed** 6/8/89  - Mensch Fix scrambler bug when using promptref is handle setitext kept derefed** 6/28/89 - Bug fix to correct problem of AuxType not getting passed onto custom draw proc.* 7/24/89 - Fixes and additions (ORR):*	Added new sort routine so lower case sorts correctly.*	Now call _errorwindow if a disk error occures on return_file.** 7/26/89 - some recent changes no-op'ed out to minimize checking for intermediate results.*	Error window and sort routine removed. Disk errors will switch to next *	volume.** 7/27/89 - sort routine added back in but this time as a List Manager proc passed*	to the toolbox routine _SortList. The routine added in this file*	is called 'CompareRoutine' and uses no local storage or variables.** 8/25/89 - Harry.  Make disk button into volumes popup. Added source file CustomPopup.aii*	which contains all the routines to create the popup, track it and*	keeps popup updated. (i.e. monitors disk switch events).*     	Disk switch event are now handled. (disk inserted becomes current volume and*	the current volume that is ejected just goes to the next drive).*	Routine MoveDialogToMemory was modified to handle custom dialogs.*	Added two new bit definitions to FGetPutFlag (bits 2 and 3 now defined)*	Fixed bug where in 320 mode the lock icon would not appear in the pathname.** 9/14/89 -  Harry	Added new entry point NextDrive1. This routine is called by CheckDiskSwitch.*	It is a subset of routine NextDrive. Instead of going to the next drive* 	we just rescan the volume in device <curDev.** 10/05/89 - Harry 	Fix bug in SFReScan. This call does not work in 320 mode. Error $1706 is *	always returned. The wrong bits were being masked off when making the check*	to see if it was OK to make the call. We were always masking out the high*	nibble when all we really wanted was bits 15 and 13 ($A000). Fixed.**	Fix bug in all the "Save" calls. When an illegal filename was entered by* 	the user they were never notified that it was bad. Instead Std File would*	just skip to the next volume. Fixed.** 11/08/89 - Harry	Fix bug in Save dialogs in 320 mode.The volume popup was not being drawn.*	Fix bug in Custom dialogs that use the volume popup. A check was being*	made to see if the item descriptor field (of the NextBut item) was zero, *	if it was then I assumed that the item was a useritem. Now I just check* 	the type of item field to determine whether to use the volume popup or *	create the "Disk" button.** 11/13/89 - Harry 	Fix BRC #53450. Limited the no. of chars that can be entered into any*	"SAVE" dialog to 35 (Previous values were 255 in the case of SFPutFile2 and*	SFPPutFile2. For SFPutFile the limit was whatever the user inputed. This is*	also limited to 35) Routine GetFilter was calling GetIText with a buffer *	limit of 36 (therefore anything exceeding this value trashed the stack)**	The default text for edit line items in "SAVE" dialogs are now selected.** 01/02/90 - Harry	The fix for no volumes on-line was not complete. There were instances where*	a disk was being inserted and not recognized. This was a problem in routine* 	GetFirst and has been fixed.** 01/15/90 - Harry 	Take out the volumes popup and put in "Volumes" button that now displays*	the list of volumes in the file list.** 01/17/90 - Harry 	Fix bug in new "PUT" calls where defining the OrigName as a resource *	would not work if the middle byte of the resource ID was zero. For some*	reason the previous author checked the middle byte of the OrigNameRef *	and if it was zero it would assume the OrigName was null. In the old "PUT" *	calls it must have been valid to push a 0 ptr as the OrigName to indicate*	there was none??????** 02/13/90 - Harry 	In the "PUT" dialogs, selecting the "NEWFOLDER" button now puts the user*	into that newly created directory. * 02/14/90 - Harry 	I now install myself into the OS notification queue. So whenever a disk*	switch event occurrs I now get called. This makes life much simpler.* 02/19/90 - Harry	Fixed bug where selecting a folder on a server volume that you didn't have*	privileges for would advance you to the next volume on-line. WS #MTLRAF009.* 02/20/90 - Harry 	If StdFile encounters a disk that GS/OS does not recognize, an alert is*	put up and the disk is ejected.* 03/01/90 - Harry	On AppleShare volumes, folders are now greyed if you do not have access*	to that folder.(fixed in routine ValidEntry) BRC #60861.* 04/04/90 - Harry 	Fix bug in SFMultiGet2. No matter how many files you selected it would  *	always return 1 as the number of files selected. Introduced in 1/15/90.*	WorkSheet #MTLRAF015.* 04/25/90 - Harry	Fix bug in GetFilter routine, which would pass <return> key hits even if*	the default button was inactive. This only caused problem in PUT dialogs*	because the <return> would then get passed to edit line items instead. *	BRC #65378.* 04/26/90 - Harry	Fixed bug where multiple volumes could be selected in "MULTI" dialogs.*	Worksheet #MTLRAF020.* 	Fixed bug in routine Convert_To_K. X-reg was suppose to contain the high*	byte of least significant 32 bit result and low byte of most significant*	32 bit result, instead we were getting middle byte of most significant*	32 bit result.  Worksheet #MTLRAF019.* 05/02/90 - Harry 	If prefix 8 or 0 (depending on whether we were making an old of new call)*	had a valid filename in it (i.e. not a directory name), StdFile would*	fail even though there were valid volume names around. Fixed.*	If an error occurred such that a "generic" error was generated this *	would cause the stack to become imbalanced. Routine GetErrorMessage was*	jsr'ed to but would not always rts. Fixed.* 06/04/90 - Harry 	Fixed bug BRC #65271. If an unformatted disk is inserted I now put up*	a dialog saying GS/OS does recognize this file system and then the disk*	is ejected.  Also fixed BRC #67012, word occurred was misspelled.* 06/27/90 - Harry	Fix problem with custom dialogs. Patching the user's dialog template causes*	problems if someone happens to unload std file and then load it again, but* 	at a different memory location. The patched addresses are now no longer*	valid. (Iduna found bug)* 07/26/90 - Harry	Re-fix, fix put in on 6/27/90. The wrong item was being unpatched. * 08/06/90 - Harry  Superfluous error dialog comes up when a 5.25" drive is scanned and there is*	no disk in it. Fixed (RAF005).  In PUT dialogs if the user enters a name*	with a colon embedded in it std file just goes to the next volume instead*	of putting up an error message. Fixed (RAF004).*	The volume list is now sorted alphabetically and selecting the first letter*	of a file in the list will now select that item in the list (RAF003).*	The CompareRoutine was modified to also do a sort on the volume list. This *	change involved the sort routine ignoring the first character of the name*	which is always a "." or a ":" (since these are volume names).** BEGIN 6.0 (???)** 18-Nov-90 Dave Lyons*	Disallowed colons in the edit line field.*	Prevent Letter-key shortcut from moving to a dimmed item (except possibly*	  the last one).* 26-Nov-90 Dave Lyons*                   Now uses ListKey to allow arbitrarily-long prefix strings in Get dialogs.*	When we set the default text in a Put dialog, now I reverse the*	  selection direction to be right-to-left for the benefit of AWGS 1.1*	  (see comment at ReverseSelection).* 4-Dec-90  Dave Lyons*	Uses ListKey for arrow-key movements, too.* 21-Dec-90 Dave Lyons*	Found and fixed that Really Annoying repeating-entry bug!  The problem*	was we weren't bumping the high word of ListPointerPtr when we added*	5 to point at the next entry.*	(At that point, we were storing *offsets* in the list, which are later*	translated into pointers.  If the handle, which was pre-zeroed, started*	near the end of a bank, then some of the offsets would get stored in*	the wrong place.  The ones that got "missed" this way stayed 0, so they*	were translated into pointers to the first item read, and then the whole*	list got sorted alphabetically.)* 6-Jan-91 Dave Lyons*	Added Apple-D, Apple-V and Apple-ESC as key equivalents for the*	  Volumes button.*	When you insert a disk & get a duplicate volume error, Std File*	  used to do nothing.  Now you get ErrorWindow($57) and it ejects.* 12-Jan-91 Dave Lyons*	Adding a framed down-arrow icon at the left of the path item.*	Clicking this pops up a menu that lets you move up as many levels*	  as you want, all the way to the Volumes/Desktop level.*	Fixing key equivalents for Open and Volumes so they honor the*	  inactive status of the corresponding buttons.* 14-Jan-91 Dave Lyons*	Finished the SeeIfItemEnabled routine use by CommonKey so the*	Open and Volumes key equivalents don't work when the buttons*	  are dimmed.*	Added a paranoia check on CloseA (never closes refnum 0).*	Prettied up the source a bit.*	Padlock icon is now drawn *after* the pathname.*	All the little icons now come from GetSysIcon & are drawn with*	  DrawIcon.*	Fixed a bug in CustomPopUp.aii (the Volume List stuff) where*	  having more than 20 volumes would hang.  (There was no code*	  to grow the list.  Now it handles 64 volumes.)* 6-Feb-91 Dave Lyons*	Added new device number parameter to InsertPathMItems call.* 5-Mar-91 Dave Lyons*	Set bit 30 of the FilterProc pointer in the ModalDialog call, so*	that the Dialog Manager will automatically track the cursor and*	make it an I-Beam & Arrow at the right times.* 14-Mar-91 Dave Lyons*	Removed Apple-V = "Volumes" because that usually means Paste.* 25-Mar-91 Dave Lyons*	New routine PollForInsertions calls the GS/OS service to scan*	  removable-media devices for new insertions.  I call this before*	  installing the notify-proc, so that old insertions that haven't*	  been noticed yet don't make SF bop to a volume unexpectedly.*	The filter proc now receives all 17 GetDirEntry parameters, including*	  the option list.*	When we're not in the volume list, sorting is done with SortList(#1)*	  for international-friendly string comparisons.* 28-Mar-91 DAL	Preserved an error code in ReDoList.*	Defined new bit in <FGetPutFlag: PutFileListActive if we're in a*	PutFile call and keystrokes should be directed to the file list.* 29-Mar-91 DAL	In custompopup.aii, fixed it so 5.25 drives are always added to the*	don't-poll list, even if they seem to be offline.* 1-Apr-91 DAL	Replaced call to DO_INSERT_SCAN with Misc Tools call ScanDevices.*	Finished the type-keys-into-the-PutFile-list stuff.  Apple-Tab*	switches you between the edit-line and the list; clicking on either*	item makes that the "target".* 2-Apr-91 DAL	Added JudgeTheName routine to call JudgeName and put up an*	AlertWindow.  Called from DoSave and DoCreate.* 7-Apr-91 DAL	At Common2, added code to load and start QDAux if it isn't started.*	Defined new error sfNotStarted, $17FF; most calls check for WAP<>0.*	SFStartUp returns the error if you pass WAP=0.* 15-Apr-91 DAL	Now calls HandleDiskInsert to do disk formatting/erasing.* 21-Apr-91 DAL	For error $57 (duplicate volume), call HandleDiskInsert.*  8-May-91 DAL	Added an InitCursor before the ErrorWindow for Replace/etc dialogs.* 10-Jun-91 DAL	¥Added check before NewModalDialog to see if both prefixes 0 and 8*	are null, and set 0 to "*:" if they are.  Avoids infinite loop!*	¥Swapped Tab and Apple-Tab.  Tab goes between target controls, and*	Apple-Tab switches volumes.*	¥Moved list control up one pixel for Put dialogs.* 8-Jul-91	DAL*	¥When tabbing to the Edit Line in a put file, we now select the text.* 31-Jul-91	DAL*	¥Experimentally removed restriction on when you can call SFReScan.*	Should always work now.* 10-Aug-91	DAL*	¥Use substitution string for "No Change" in bad-name dialog.* 26-Aug-91	DAL*	¥Standard Draw routine checks for 640 mode & an odd window position;*	if needed, it draws the GetSysIcon icon at an odd local coordinate*	to make the colors come out right.* 3-Sep-91	DAL*	¥JudgeName dialog now calls InitCursor.* 15-Sep-91	DAL*	¥Fix the 26-Aug fix, I need to check the pen position, too.  No*	more green folders.  Really, this time!*	¥DoUnPatch was not working right (at least not in all cases) becuase*	it thought it was working with the user's original dialog template,*	when it was actually working with a template computed from the*	original (by MoveDialogToMemory), where the items were in a confusing*	order.  Added OrigDialogTempPtr so I can unpatch correctly.*	¥Fixed the "inifinite please format your HFS partition problem" by*	marking non-removable devices as don't-poll, even in the case that*	the Volume call fails.* 21-Oct-91	DAL*	¥Avoid constantly flickering the cursor: focus frame update only for*	my own update events, not for any pending update event.* 1-Nov-91	DAL*	¥In VerbCheck, verify the SF2-style Reply Record only if it's not a*	SFMultiGet2 call!  This was causing occasional flakey $1705 errors*	for some folks (or at least for Bryan P at Softdisk).  It was trying*	to validate fields that were beyond the end of the 6-byte multi reply*	record.* 18-Dec-91	DAL*	¥Added FunkyPutFile bit--special handling for PutFile dialogs with*	the Line Edit box outside the window (always direct keys to the list,*	but never draw the focus frame around the list).  Also, don't fudge*	the List upwards by a pixel when it's a FunkyPutFile.*	¥JudgeTheName does not rely on FrontWindow to get the dialog ptr*	(because Bryan P has already hidden the window!).*	¥In DoPathDraw, now we set the clip region so we don't draw outside*	the path item rectangle.*	¥DoPathDraw now stores the right edge of what we drew, and DoPath*	ignores any clicks to the right of this position.*	¥SFRescan takes no action if you're at the Volumes list (no error).*	¥Up and Down arrows in PutFile volume list now update the K free/used*	for the correct disk.* 29-Jan-92	DAL (for 6.0d68)*	¥Fixed convert_time to respect the 1940..2039 definition of a class-0*	date value (out-of-range dates are returned as all-zero date/time).*	¥Mess with sys prefs around GetDevNumber in GetThePrefix, to avoid*	prompting for offline disk (if the prefix happens to be set to one).*	¥If we get an error building the file list, now we call ErrorWindow,*	and then try again with the root level of the boot volume.* 6-Feb-92	DAL (for 6.0d70)*	¥Drawing the padlock in the path item adjusts the pen position so it*	won't get overwritten by the file system text.*	¥You can click on the FST name to pop down the path menu (moved one*	line).******************************************************************************************* BEGIN 6.0.1** 17-Feb-92	DAL*	¥Make Command-left and Command-right cycle volumes?** 5-Mar-92	DAL (for 6.1d2)*	¥Change Long2Dec calls to set bit 31 of stringPtr for "zero K"*	(net savings of 31 bytes by consolidating into Long2DecTen)** 16-Mar-92	DAL*	¥Regular item-draw uses DrawStringWidth instead of manually*	setting charExtra.** 25-Mar-92	DAL*	¥Updated messages to read "Disks" instead of "Volumes".** 27-Apr-92	DAL*	¥Volume name comparison in NextDrive is now case-insensitive.**  5-Oct-92	DAL*	¥Passes real auxiliary type to GetSysIcon (was always passing zero).** 17-19-Mar-93 SS*	¥Fixed SFReScan to update _all_ controls when called.*	¥Added key equivalent: Cmd-Shift-Up = Cmd-D = hit in Disks button.*	¥Added key equivalent: Cmd-Rt-Arrow = Cmd-Tab = fwd to next drive.*	¥Added new key support: Cmd-Lt-Arrow = backward to previous drive.*	Defined new bit in <FGetPutFlag: TabBackwards for NextDrive to know*	which direction to go through the devices.  Set = go backwards (duh!).*	¥Added a content draw proc to update the dlg window if something moves*	across in front.*	¥Added call to UpdateWindow to attempt to update windows behind us.*	¥Made several changes to try to handle multiple editlines in PutFile.*	Un-hard-coded references to Item#10 (previously the only editline).*	Added a fake off-screen editline item #8 to represent the List.	** 22-Mar-93 SS*	¥Fixed PromptDesc error check in VerbCheck.  A 'BadVerbPrompt' error*	was never being reported!  This also allowed removing several occurances*	of 'and #3' that are no longer needed after the range checking is done.*	Need a reminder in the doc that PromptRefDesc >3 is invalid.* 23-Mar-93 SS*	¥Added remainder of code to support multiple edit lines in PutFile.* 25-Mar-93 SS*	¥Made SFReScan work in the volume list (as well as the file list).** 2-Apr-93 SS*	¥Fixed DoExit - it was not properly releasing the prompt if it was a resource.** 6-May-93 DAL/SS	¥Changed NextDrive1 to avoid an infinite loop if Seperator (sic) was not set*	up yet.  This happened if prefix 0 was empty on an SFGetFile call.******************************************************************************************	print push	print off		INCLUDE 'all.macros'	Include 'Dave.Macros'	INCLUDE 'E16.Event'	INCLUDE 'E16.Dialog'	INCLUDE 'E16.List'	INCLUDE 'E16.Menu'	INCLUDE 'E16.Control'	INCLUDE '::sys.equs.asm'	print pop	string asis	ENTRY DerefandLock	ENTRY SaveAndZeroRefCons	ENTRY GetLocInfo		ENTRY BuildList	ENTRY GetFirst	ENTRY DirectoryUp	ENTRY DirectoryDown	ENTRY ReadDirSize	ENTRY GetNewHandle	ENTRY GetSmallHandle	ENTRY KillHandle	ENTRY ExtendHandle	ENTRY GetThePrefix	ENTRY OpenPrefix	ENTRY ClosePrefix	ENTRY SetThePrefix	ENTRY CloseA	ENTRY ReadNextDirEntry	ENTRY PathDraw	ENTRY DoPathDraw	ENTRY GetSelected	ENTRY DoDInfoCall	ENTRY PutAdjust	ENTRY CommonOpen	ENTRY DeRefHandle	ENTRY MoveDialogToMemory	ENTRY KillPointer		INCLUDE 'GlobalEqu.aii'*********************************************************************** Dialog Record files**********************************************************************	INCLUDE 'Dialogs.aii'	INCLUDE 'CustomPopUp.aii'	SFGet	PROC	EXPORT SFGetFile2	EXPORT SFGetFile	EXPORT SFPGetFile2	EXPORT SFPGetFile	EXPORT SFMultiGet2	EXPORT SFPMultiGet2	rtl************************************************************************ StdGetFile** Entry to Get.** The stack: Different for each entry point.** This is the define stack for SFGetFile2***********************************************************************	DefineStackorigD	wordorigB	byte	;reserve word on stackRtl1	block 3	;(like r long but adds space for 3 bytes)Rtl2	block 3SGReplyPtr2	long	;POINTER to a reply record (see calling routine for def).SGTypeListPtr2	long	;POINTER to typelist record; NIL to display all files.SGFilterProcPtr2	long	;POINTER to filter procedure; NIL for none.SGPromptPtr2	long	;POINTER to string to display at top of dialog.SGPromptVerb2	word	;Prompt string verb.SGWhereY2	word	;Y corrdinate of upper left corner.SGWhereX2	word	;X coordinate of upper left corner.SGStack2	equ DummyPC-10	;stack size** The folowing is the define stack for SFPGetFile2*	DSect 10SGReplyPtrP2	long	;POINTER to a reply record (see calling routine for def).SGDilgHookPtrP2	long	;POINTER to a routine called every time ModalDialog returns a hitSGDilgPtrP2	long	;POINTER to a dialog template in memory.SGTypeListPtrP2	long	;POINTER to typelist record; NIL to display all files.SGFilterProcPtrP2	long	;POINTER to filter procedure; NIL for none.SGPromptPtrP2	long	;POINTER to string to display at top of dialog.SGPromptVerbP2	word	;Prompt string verb.SGItemDrawPtrP2	long	;POINTER to a list member draw routine.SGWhereYP2	word	;Y corrdinate of upper left corner.SGWhereXP2	word	;X coordinate of upper left corner.SGPStack2	equ DummyPC-10	;stack size	** This is the define stack for the old SFGetFile*	DSect 10SGReplyPtr	long	;POINTER to a reply record (see calling routine for def).SGTypeListPtr	long	;POINTER to typelist record; NIL to display all files.SGFilterProcPtr	long	;POINTER to filter procedure; NIL for none.SGPromptPtr	long	;POINTER to string to display at top of dialog.SGWhereY	word	;Y corrdinate of upper left corner.SGWhereX	word	;X coordinate of upper left corner.SGStack	equ DummyPC-10	;stack size** The folowing is the define stack for the old SFPGetFile*	DSect 10SGReplyPtrP	long	;POINTER to a reply record (see calling routine for def).SGDilgHookPtrP	long	;POINTER to a routine called every time ModalDialog returns a hitSGDilgPtrP	long	;POINTER to a dialog template in memory.SGTypeListPtrP	long	;POINTER to typelist record; NIL to display all files.SGFilterProcPtrP	long	;POINTER to filter procedure; NIL for none.SGPromptPtrP	long	;POINTER to string to display at top of dialog.SGWhereYP	word	;Y corrdinate of upper left corner.SGWhereXP	word	;X coordinate of upper left corner.	SGPStack	equ DummyPC-10	;stack size** Exit:	Errors returned in A, carry set.* The stack:	empty.************************************************************************* Entry SFMultiGet2*SFMultiGet2	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	lda #MultiFileMode	bra GetFile2************************************************************************ Entry for SFGetFile2*SFGetFile2	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	lda #0000		;GET, NEWGetFile2	sta ztemp1		;flags here	jsr reset_vars** Move all incomming parameters off the stack and into zero-page.*	lda SGReplyPtr2,s		; Transfer parameters on	sta ReplyPtr		; the stack to zero-page.	lda SGReplyPtr2+2,s	sta ReplyPtr+2*--------------------------------------------------------------------------------	lda SGTypeListPtr2,s	sta TypeList	lda SGTypeListPtr2+2,s	sta TypeList+2*--------------------------------------------------------------------------------	lda SGFilterProcPtr2,s	sta FilterProcPtr	lda SGFilterProcPtr2+2,s	sta FilterProcPtr+2*--------------------------------------------------------------------------------	lda SGPromptVerb2,s	sta PromptVerb	lda SGPromptPtr2,s	sta PromptPtr	lda SGPromptPtr2+2,s	sta PromptPtr+2*--------------------------------------------------------------------------------	lda SGWhereX2,s	sta WhereX	lda SGWhereY2,s	sta WhereY		lda #SGStack2		;stack size	sta stacksize		;bytes need removing	brl common************************************************************************ Entry SFPMultiGet2*SFPMultiGet2	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	lda #PatchedFlag+MultiFIleMode	bra PGetFile2************************************************************************ Entry for SFPGetFile2*SFPGetFile2	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	lda #PatchedFlag		;GET, NEWPGetFile2	sta ztemp1		;flags here	jsr reset_vars		lda SGReplyPtrP2,s		; Transfer parameters on	sta ReplyPtr		; the stack to zero-page.	lda SGReplyPtrP2+2,s	sta ReplyPtr+2*--------------------------------------------------------------------------------	lda SGDilgHookPtrP2,s	; Transfer parameters on	sta DilgHook		; the stack to zero-page.	lda SGDilgHookPtrP2+2,s	sta DilgHook+2*--------------------------------------------------------------------------------	lda SGDilgPtrP2,s		; Transfer parameters on	sta DialogTemplatePtr	; the stack to zero-page.	lda SGDilgPtrP2+2,s	sta DialogTemplatePtr+2*--------------------------------------------------------------------------------	lda SGTypeListPtrP2,s	sta TypeList	lda SGTypeListPtrP2+2,s	sta TypeList+2*--------------------------------------------------------------------------------	lda SGFilterProcPtrP2,s	sta FilterProcPtr	lda SGFilterProcPtrP2+2,s	sta FilterProcPtr+2*--------------------------------------------------------------------------------	lda SGPromptVerbP2,s	sta PromptVerb	lda SGPromptPtrP2,s	sta PromptPtr	lda SGPromptPtrP2+2,s	sta PromptPtr+2*--------------------------------------------------------------------------------	lda SGItemDrawPtrP2,s	sta IconHookPtr	lda SGItemDrawPtrP2+2,s	sta IconHookPtr+2*--------------------------------------------------------------------------------	lda SGWhereXP2,s	sta WhereX	lda SGWhereYP2,s	sta WhereY	lda #SGPStack2		;stack size	sta stacksize		;34 bytes need removing	brl commonSFGetFile************************************************************************ Entry for SFGetFile***********************************************************************	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	jsr reset_vars** Move all incomming parameters off the stack and into zero-page.*	lda SGReplyPtr,s		; Transfer parameters on	sta ReplyPtr		; the stack to zero-page.	lda SGReplyPtr+2,s	sta ReplyPtr+2*--------------------------------------------------------------------------------	lda SGTypeListPtr,s	sta TypeList	lda SGTypeListPtr+2,s	sta TypeList+2*--------------------------------------------------------------------------------	lda SGFilterProcPtr,s	sta FilterProcPtr	lda SGFilterProcPtr+2,s	sta FilterProcPtr+2*--------------------------------------------------------------------------------	lda SGPromptPtr,s	sta PromptPtr	lda SGPromptPtr+2,s	sta PromptPtr+2*--------------------------------------------------------------------------------	lda SGWhereX,s	sta WhereX	lda SGWhereY,s	sta WhereY	lda #SGStack		;stack size	sta stacksize		;20 bytes need removing	lda #OldStyleFlag		;OLD GET	brl common2	SFPGetFile************************************************************************ Entry for SFPGetFile***********************************************************************	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	jsr reset_vars	lda SGReplyPtrP,s		; Transfer parameters on	sta ReplyPtr		; the stack to zero-page.	lda SGReplyPtrP+2,s	sta ReplyPtr+2*--------------------------------------------------------------------------------	lda SGDilgHookPtrP,s	; Transfer parameters on	sta DilgHook		; the stack to zero-page.	lda SGDilgHookPtrP+2,s	sta DilgHook+2*--------------------------------------------------------------------------------	lda SGDilgPtrP,s		; Transfer parameters on	sta DialogTemplatePtr	; the stack to zero-page.	lda SGDilgPtrP+2,s	sta DialogTemplatePtr+2*--------------------------------------------------------------------------------	lda SGTypeListPtrP,s	sta TypeList	lda SGTypeListPtrP+2,s	sta TypeList+2*--------------------------------------------------------------------------------	lda SGFilterProcPtrP,s	sta FilterProcPtr	lda SGFilterProcPtrP+2,s	sta FilterProcPtr+2*--------------------------------------------------------------------------------	lda SGPromptPtrP,s	sta PromptPtr	lda SGPromptPtrP+2,s	sta PromptPtr+2*--------------------------------------------------------------------------------	lda SGWhereXP,s	sta WhereX	lda SGWhereYP,s	sta WhereY	lda #SGPStack		;stack size	sta stacksize		;28 bytes need removing	lda #PatchedFlag+OldStyleFlag	;OLD GET, Custom dialog	brl common2		ENDPSFReScan2	PROC EXPORT** The folowing is the define stack for the old SFReScan2 entry	DSect 10SRTypeListPtr	long	;POINTER to typelist record; NIL to display all files.SRFilterProcPtr	long	;POINTER to filter procedure; NIL for none.SFRStack	equ DummyPC-10	;stack size************************************************************************ Entry for SFReScan2***********************************************************************	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb*--------------------------------------------------------------------------------*** let it happen at the volume level also  25-Mar-93 SS;*** added 18-Dec-91 DAL -- If we're at the Volume level, do nothing;	lda FGetPutFlag;	and #inVolumeList;	bne @exit*** 31-Jul-91 DAL -- Remove restrictions and see if this works for everything;	lda FGetPutFlag;	and #$A000		;only necessary bits 15 and 13. HY 10/5/89;	cmp #$2000		;patched gets only;	beq @1		;not ok;	ldx #$1706		;bad call error;	ldy #SFRStack		;stack size;	brl ErrorEscape2		;good bye!*--------------------------------------------------------------------------------@1	lda SRTypeListPtr+1,s	;zero?	beq @2	lda SRTypeListPtr,s	sta TypeList	lda SRTypeListPtr+2,s	sta TypeList+2*--------------------------------------------------------------------------------@2	lda SRFilterProcPtr+1,s	beq @3	lda SRFilterProcPtr,s	sta FilterProcPtr	lda SRFilterProcPtr+2,s	sta FilterProcPtr+2*--------------------------------------------------------------------------------@3*** Added to force all controls to update in case pfx8 is on another drive. 17-Mar-93 SS	lda #8	jsr GetThePrefix	jsr DoDInfoCall	jsr DoVolumeCall	lda FGetPutFlag	bit #PutFlag	beq @inGet		PushZLong DialogPtr	_SetPort		;make sure the port is set.	PushZLong DialogPtr	PushWord #11		;kbFreeStr item	PushZPtr tempRect	_GetDItemBox	PushZPtr tempRect	_InvalRect		;rect is invalid and should redraw@inGet*** end 17-Mar-93 SS	lda #$8000	sta FRedraw@exit	ldx #0000	ldy #SFRStack		;stack size	brl ErrorEscape2		;and leave		ENDP		SFPutFile2	PROC EXPORT	EXPORT SFPutFile	EXPORT SFPPutFile	EXPORT SFPPutFile2************************************************************************ StdPutFile entries: SFPutFile, SFPPutFile, SFPutFile2, SFPPutFile2** Entry to Put.* The stack: 	Different for each entry point** This is the define stack for SFPutFile2***********************************************************************	DefineStackorigD	wordorigB	byte	;reserve word on stackRtl1	block 3	;(like r long but adds space for 3 bytes)Rtl2	block 3SReplyPtr2	long	;POINTER to a reply record (see calling routine for def).SorigNamePtr2	long	;POINTER to string that holds default name for text edit field.SorigNameVerb2	word	;Default name string verb.SPromptPtr2	long	;POINTER to prompt string.SPromptVerb2	word	;Prompt string verb.SWhereY2	word	;Y corrdinate of upper left corner.SWhereX2	word	;X coordinate of upper left corner.SPStack2	equ DummyPC-10	;stack size*** This is the define stack for SFPPutFile2*	DSect 10SReplyPtrP2	long	;POINTER to a reply record (see calling routine for def).SDilgHookPtrP2	long	;POINTER to a routine called every time ModalDialog returns a hitSDilgPtrP2	long	;POINTER to a dialog template in memory.SorigNamePtrP2	long	;POINTER to string that holds default name for text edit field.SorigNameVerbP2	word	;Default name string verb.SPromptPtrP2	long	;POINTER to prompt string.SPromptVerbP2	word	;Prompt string verb.SPItemDrawPtrP2	long	;POINTER to a list member draw routine.SWhereYP2	word	;Y corrdinate of upper left corner.SWhereXP2	word	;X coordinate of upper left corner.SPStackP2	equ DummyPC-10	;stack size*** This is the define stack for the old SFPutFile*	DSect 10SReplyPtr	longSMaxLen	word	;max length user may typeSorigNamePtr	longSPromptPtr	longSWhereY	wordSWhereX	wordSPStack	equ DummyPC-10	;stack size*** This is the define stack for the old SFPPutFile*	DSect 10SReplyPtrP	long	;POINTER to a reply record (see calling routine for def).SDilgHookPtrP	long	;POINTER to a routine called every time ModalDialog returns a hitSDilgPtrP	long	;POINTER to a dialog template in memory.SMaxLenP	word	;max length user may typeSorigNamePtrP	longSPromptPtrP	longSWhereYP	wordSWhereXP	wordSPStackP	equ DummyPC-10	;stack size*** Exit:	Errors returned in A, carry set.** The stack:	empty.************************************************************************* entry for SFPutFile2*	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	jsr reset_vars** Move all incomming parameters off the stack and into zero-page.*	lda SReplyPtr2,s		; Transfer parameters on	sta ReplyPtr		; the stack to zero-page.	lda SReplyPtr2+2,s	sta ReplyPtr+2*--------------------------------------------------------------------------------	lda SorigNameVerb2,s	sta OrigNameVerb	lda SorigNamePtr2,s	sta OrigName	lda SorigNamePtr2+2,s	;can use typlist here.	sta OrigName+2*--------------------------------------------------------------------------------	lda SPromptVerb2,s	sta PromptVerb	lda SPromptPtr2,s	sta PromptPtr	lda SPromptPtr2+2,s	sta PromptPtr+2*--------------------------------------------------------------------------------	lda #32		;real long names ok	sta MaxLen		;no max len passed here*--------------------------------------------------------------------------------	lda SWhereX2,s	sta WhereX	lda SWhereY2,s	sta WhereY		lda #SPStack2		;stack size	sta stacksize		;24 bytes need removing	lda #PutFlag		;PUT	brl common2** entry for SFPPutFile2*SFPPutFile2	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	jsr reset_vars** Move all incomming parameters off the stack and into zero-page.*	lda SReplyPtrP2,s		; Transfer parameters on	sta ReplyPtr		; the stack to zero-page.	lda SReplyPtrP2+2,s	sta ReplyPtr+2*--------------------------------------------------------------------------------	lda SDilgHookPtrP2,s	; Transfer parameters on	sta DilgHook		; the stack to zero-page.	lda SDilgHookPtrP2+2,s	sta DilgHook+2*--------------------------------------------------------------------------------	lda SDilgPtrP2,s		; Transfer parameters on	sta DialogTemplatePtr	; the stack to zero-page.	lda SDilgPtrP2+2,s	sta DialogTemplatePtr+2*--------------------------------------------------------------------------------	lda SorigNameVerbP2,s	sta OrigNameVerb	lda SorigNamePtrP2,s	sta OrigName	lda SorigNamePtrP2+2,s	sta OrigName+2*--------------------------------------------------------------------------------	lda #32		;real long names ok	sta MaxLen		;no max len passed here*--------------------------------------------------------------------------------	lda SPromptVerbP2,s	sta PromptVerb	lda SPromptPtrP2,s	sta PromptPtr	lda SPromptPtrP2+2,s	sta PromptPtr+2*--------------------------------------------------------------------------------	lda SPItemDrawPtrP2,s	sta IconHookPtr	lda SPItemDrawPtrP2+2,s	sta IconHookPtr+2*--------------------------------------------------------------------------------	lda SWhereXP2,s	sta WhereX	lda SWhereYP2,s	sta WhereY*--------------------------------------------------------------------------------	lda #SPStackP2	sta stacksize		;33 bytes need removing	lda #PutFlag+PatchedFlag	;PUT, Custom dialog (#$A000)	brl common2SFPutFile** entry for original SFPutFile*	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	jsr reset_vars** Move all incomming parameters off the stack and into zero-page.*	lda SReplyPtr,s		; Transfer parameters on	sta ReplyPtr		; the stack to zero-page.	lda SReplyPtr+2,s	sta ReplyPtr+2*--------------------------------------------------------------------------------	lda SMaxLen,s	cmp #33		; make sure that max chars. that can be	bcc StoreIt		; entered into edit line item does not	lda #32		; exceed 36. StoreIt	sta MaxLen*--------------------------------------------------------------------------------	lda SorigNamePtr,s	sta OrigName	lda SorigNamePtr+2,s	;can use typlist here.	sta OrigName+2*--------------------------------------------------------------------------------	lda SPromptPtr,s	sta PromptPtr	lda SPromptPtr+2,s	sta PromptPtr+2*--------------------------------------------------------------------------------	lda SWhereX,s	sta WhereX	lda SWhereY,s	sta WhereY	lda #SPStack	sta stacksize		;18 bytes need removing	lda #PutFlag+OldSTyleFlag	;PUT, OLD (#$8001)	bra common2** entry for SFPPutFile*SFPPutFile	phd		; Save Direct Page Register.	tcd		; Put ours.	phb		; Save Data Bank register.	phk		; Put ours.	plb	jsr reset_vars** Move all incomming parameters off the stack and into zero-page.*	lda SReplyPtrP,s		; Transfer parameters on	sta ReplyPtr		; the stack to zero-page.	lda SReplyPtrP+2,s	sta ReplyPtr+2*--------------------------------------------------------------------------------	lda SDilgHookPtrP,s	; Transfer parameters on	sta DilgHook		; the stack to zero-page.	lda SDilgHookPtrP+2,s	sta DilgHook+2*--------------------------------------------------------------------------------	lda SDilgPtrP,s		; Transfer parameters on	sta DialogTemplatePtr	; the stack to zero-page.	lda SDilgPtrP+2,s	sta DialogTemplatePtr+2*--------------------------------------------------------------------------------	lda SMaxLenP,s	cmp #33	bcc @StoreIt	lda #32@StoreIt	sta MaxLen*--------------------------------------------------------------------------------	lda SorigNamePtrP,s	sta OrigName	lda SorigNamePtrP+2,s	;can use typlist here.	sta OrigName+2*--------------------------------------------------------------------------------	lda SPromptPtrP,s	sta PromptPtr	lda SPromptPtrP+2,s	sta PromptPtr+2*--------------------------------------------------------------------------------	lda SWhereXP,s	sta WhereX	lda SWhereYP,s	sta WhereY	lda #SPStackP	sta stacksize		;26 bytes need removing	lda #PutFlag+PatchedFlag+OldStyleFlag	;#$A001  ;PUT, OLD, Custom dialog	bra common2	;safe way to fall through	ENDP************************************************************************ Common point for all of above entries. A = FGetPutFlag value.***********************************************************************common	PROC EXPORT	EXPORT common2	EXPORT ErrorEscape	EXPORT ErrorEscape2	EXPORT Main_Exit		lda ztemp1		;temp storage for flagscommon2	sta FGetPutFlag		;Flags	sta closeButStat		;a state it can't be	sta saveButStat		;another impossible state!	stz CurError		;No error (so far!!)	lsr a		;old style call in d0 now in carry	bcs @1		;no error check in verbs in old calls	jsr VerbCheck		;check verbs on new calls	bcc @1		;no errors	sta CurError		;what error	tax		;ErrorEscape need this in x	brl ErrorEscape		;and leave quickly@1*** added 7-Apr-91 DAL -- make sure we're actually started up!*** (If we're not, we already trashed some zero page, but tough shit.)	tdc	bne @started	ldx #sfNotStarted	brl ErrorEscape@started*** end of 7-Apr-91 DAL*** added 7-Apr-91 DAL -- make sure QD Aux is available!	pea 0	_QDAuxStatus	pla	bne @gotQDAux	pea $0012	;QuickDraw II Auxiliary	pea $0304	;minimum QDAux version $0304	_LoadOneTool	bcc @loadedQDAux	tax	brl ErrorEscape@loadedQDAux	_QDAuxStartUp@gotQDAux*** end of 7-Apr-91 DAL	PushLongSpace	_GetPort*******************will leave this on the stack and remove it later*********	** Now allocate most of the needed memory** get a zero length handle (gets killed and reallocated upon first entry to BuildList* but I needed something for BuildLIst to be able to kill.*	lda #0	jsr GetSmallHandle	bcc No_memErrorMem_Error_brl	brl Main_Exit		;a place to branch (will save error)No_memError	stax ListPointerHandle** Allocate a parameter buffer in memory to save the current working prefix*	lda #512		;512 bytes for handle	jsr GetSmallHandle	bcs Mem_Error_brl	PushAx		;push for the derefandlock	jsr DerefAndLock		;returns a pointer to memory	stax PrefixPtr	lda #508		;length of this buffer (-4 to CYA)	sta [PrefixPtr]** a place in memory for the list of file name strings*	lda #512		;512 bytes to start	jsr GetSmallHandle	bcs Mem_Error_brl	stax StringsHandle		;a place to start saving strings	PushAx		;push for the derefandlock	jsr DerefAndLock		;returns a pointer to memory	stax StringsPtr** Allocate a buffer in memory for the GetDirectory call to use for the* name string returned. This will grow later if a larger area is needed.* This area can also be used for temp storage when not doing directory calls.*	lda #256+4		;256 bytes for handle (+ 4 overhead)	jsr GetSmallHandle		;should be plenty (will grow if needed)	bcs Mem_Error_brl	stax NameHandle	PushAx		;push for the derefandlock	jsr DerefAndLock		;returns a pointer to memory	stax NamePtr	lda #256		;length of this buffer (-4 to CYA)	sta [NamePtr]** This memory is used by the DInfo call as a place to put its results* Actually, I think I'll make this even larger and use the area for temp storage as well (12/19/88)*	lda #135		;35 bytes for handle +100 for temps	jsr GetSmallHandle	bcs Mem_Error_brl	PushAx		;push for the deref	jsr DerefandLock		;returns a pointer to memory	stax DinfoPtr	lda #131		;length of this buffer (-4 to CYA)	sta [DinfoPtr]** This memory is used to put the list manager record into.*	lda #40		;40 bytes for the record	jsr GetSmallHandle		;handle of memory	bcs Mem_Error_brl	stax ListRecHandle	PushAx		;push for the deref	jsr DerefandLock		;returns a pointer to memory	stax ListRecPtr** now some memory for Get to display drive's stat (need to make them strings)*	lda #32		;32 bytes for the record* (see globalequ.aii for allocation and use of this block)	jsr GetSmallHandle		;handle of memory	bcs Main_Exit	PushAx		;push for the deref	jsr DerefandLock		;returns a pointer to memory	stax SizeInfoPtr** a small buffer for GetDirEntry conversion to old ProDos call style for Filter Procs*	lda FGetPutFlag	bmi skipBuffer		;not needed for Put	lsr a		;see if an old call	bcc skipBuffer		;only for an old call** Cheat: instead of lda and ora a long address, check second and third byte. Not likely* both will be 0.	lda FilterProcPtr+1		;is there a User Hook ?	beq skipBuffer		;not needed if no hook		lda #40		;approx 38 bytes for the record	jsr GetSmallHandle		;handle of memory	bcs Main_Exit	PushAx		;push for the deref	jsr DerefandLock		;returns a pointer to memory	stax ProDosDirEntry		;save the pointerskipBuffer** we have all the memory we need!** now some last minute set up stuff*		stz lastSelected	stz lastSelected+2		;lastselected item init	lda #$FFFF	sta openButStat		;init to impossible state (so it detects a change!)	jsr GetLocInfo		;Need to know which size we are in?	bne @1	lda #Size320Flag	ora FGetPutFlag	sta FGetPutFlag		;d15 = 1 is 320 mode@1** Set up near done.....FGetPutFlag contains size info and Get/Put info** Select proper dialog*	lda FGetPutFlag	bit #PatchedFlag		;see if custom dialog	beq Not_patched	ldax DialogTemplatePtr	bra Patched_moveNot_patched	and #$C000		;keep only dialog type bits	xba		;d15/16 to d7/8	lsr a		;d7/8 to d6/7	lsr a		;d7/8 to d5/6	lsr a		;d7/8 to d4/5	lsr a		;d7/8 to d3/4	tax	lda DialogTable,x	pha	inx	inx	lda DialogTable,x	tax	plaPatched_move	jsr MoveDialogtoMemory	;pass pointer in a,x, returns pointer to new template	sta DialogTemplatePtr	;return template in memory	stx DialogTemplatePtr+2do_custom		jsr Common_Patched		;Do GetFile or PutFile.** return point and exit (carry = error if set, a = error code (I hope I didn't miss any)*Main_exit	bcc @3	pha	lda #0	sta [ReplyPtr]		;if error, turn off Good	pla	sta CurError		;save any error if one!	cmp #$0201		;memory error	bne @3		;skip the rest** if a memory error, find out how much space is left BEFORE getting rid of the handles*	PushLongSpace	_MaxBlock		;ask the system whats avaliable** total free is on the stack*	ldax SizeInfoPtr	clc	adc #totalSizeStr		;point to place for string	bcc @1	inx@1	PushAX	stax [SizeInfoPtr],totalSize	;save as a "mini table";	PushWord #0010		;10 characters;	PushWord #False		;unsigned;	_Long2Dec		;string set up	jsr Long2DecTen	;5-Mar-92 DAL** What did we request*	PushLong LastRequest	;size last requested	ldax SizeInfoPtr	clc	adc #totalFreeStr		;point to place for string	bcc @2	inx@2	PushAX		;destination of string 2	stax [SizeInfoPtr],totalFree	;second "mini table" entry;	PushWord #0010		;10 characters;	PushWord #False		;unsigned;	_Long2Dec		;string set up 2	jsr Long2DecTen	;5-Mar-92 DAL@3********************the original port was left on the stack above********************	_SetPort** the exit from get file*	lda FGetPutFlag	and #PathDrawPatched	beq NotPatched		jsr DoUnPatchNotPatched	lda #1	sta ParBlock	lda #NotificationPROC	;de-install ourselves from the 	sta procPointer		;OS notification queue	lda #^NotificationPROC	sta procPointer+2	PushZPtr ParBlock		;pointer to parameter block	PushWord #$2035		;_DelNotifyProc	jsl ProDos_Stack_Entry	;stack based call		ldax ListPointerHandle	jsr KillHandle		ldax StringsHandle		;a place to start saving strings	jsr KillHandle	ldax NameHandle	jsr KillHandle		ldax ListRecHandle	jsr KillHandle		; release memory	ldax PrefixPtr	jsr KillPointer	ldax DinfoPtr	jsr KillPointer		; release memory	ldax DialogTemplatePtr	jsr KillPointer	lda FGetPutFlag	bmi skipremove		;not done if Put	lsr a		;see if an old call	bcc skipremove		;only for an old call	lda FilterProcPtr+1		;is there a User Hook ? (cheat check)	beq skipremove		;not needed if no hook		ldax ProDosDirEntry		;save the pointer	jsr KillPointerskipremove		lda CurError	beq @1		;forget check if error	cmp #$0201		;memory error	bne @1		;skip the rest	ldy #TotalSizeStr+10	;where the string starts	lda #0	sta [SizeInfoPtr],y	;make a c string	ldy #TotalFreeStr+10	sta [SizeInfoPtr],y	PushWordSpace		;results for alert window	PushWord #0		;indicate C string	PushLong SizeInfoPtr	;substitution array	PushLong #MemoryMessage	;tell them error	_AlertWindow	pla		;don't care what comes back	lda CurError		;and pass back the error@1	pha		;save current error to kill one more handle	ldax SizeInfoPtr	jsr KillPointer		;last one that may have been needed	plx		;put error in x for ToStrip	stz FGetPutFlag		;clear the flag when we leave!ErrorEscape	ldy stacksizeErrorEscape2** better have stack size in Y and error code in X*	plb	pld	jml ToStrip		*********************************************************************** There is a problem with patching the user's dialog template with an* address that points to a routine in Standard File.  If standard file* happens to get unloaded and then loaded again but in a different * memory location then this address is no longer valid the next time* this dialog template is used.  Therefore to make sure standard file* always patches out this field we reset it to zero.**********************************************************************doUnPatch	;;;	lda DialogTemplatePtr	;move ptr to dialog template to another 	lda >origDialogTempPtr	;15-Sep-91 DAL	sta pointer2		;dpage location;;;	lda DialogTemplatePtr+2	lda >origDialogTempPtr+2	;15-Sep-91 DAL	sta pointer2+2		bit FGetPutFlag		;find out if it's Get or Put dialog	bmi @ItsPut		ldy #34		;offset for get dialog header to path item (item 6)	bra @doit	@ItsPut	ldy #38		;offset for put dialog header to path item (item 7)	@doit	lda [<pointer2],y		;get ptr to dialog item	tax		;and put ptr in dpage location	iny	iny	lda [<pointer2],y	sta <pointer2+2	stx <pointer2		ldy #12		;offset to refdescriptor field	lda #0		;Zero this location out so that std file will patch	sta [<pointer2],y		;this out the next time the template is used.	iny	iny	sta [<pointer2],y		rts	export OrigDialogTempPtrOrigDialogTempPtr	dc.l 0	ENDP************************************************************************ Check incomming verbs for valid values and set carry and return error* if any one is bad. Note that we stop checking as soon as one bad verb* is found.***********************************************************************VerbCheck	PROC EXPORT	import ffListHandle	;DAL*** added 1-Nov-91 DAL -- SFMultiGet2 does NOT have this kind of reply record to check!	lda <fGetPutFlag	and #MultiFileMode	bne @itsMultiFile*** end 1-Nov-91 DAL** Check reply record name verb*	ldy #NewReplyRecord.NnameVerb	;name verb	** legit values for this verb are 0, 1, & 3*	lda [ReplyPtr],y		;verb value	cmp #2		;not allowed in a reply record	bne @1		;it's OK	sec	lda #BadVerbRRName		;bad verb	rts		;return error@1** check reply record path verb*	ldy #NewReplyRecord.NpathVerb	;path verb	** legit values for this verb are 0, 1, & 3*	lda [ReplyPtr],y		;verb value	cmp #2		;not allowed in a reply record	bne @2	sec	lda #BadVerbRRPath		;bad verb	rts		;return error@2@itsMultiFile** Check incomming parameters: First Prompt as all calls have a prompt*	lda PromptVerb		;legit values 0,1,2;	and #$0003	;*** removed to allow error to be reported! 22-Mar-93 SS	cmp #0003		;bad values	bcc @3		;ok value	lda #BadVerbPrompt	sec	rts@3** Name string on Put files*	bit FGetPutFlag		;if put, check default name string	bpl @4	lda OrigNameVerb 	cmp #0003		;bad values	bcc @4		;ok value	lda #BadVerbName	sec	rts@4	clc	rts*********************************************************************** Common code section for Get and Put File calls**********************************************************************Common_Patched	PROC EXPORT	with PopUpGlobals	with OldReplyRecord	with NewReplyRecord		IMPORT BuildVolumeList	IMPORT VolumesOnLine	IMPORT PollDevices	IMPORT ServiceDiskSwitch	IMPORT NotificationPROC	IMPORT PutUpAlert	import PollForInsertions	;25-Mar-91 DAL	import PathItemRightEdge	;18-Dec-91 DAL	import UpdateTheDialog	;19-Mar-93 SS