eft selection* reverse beginning/end	tax	;keep beginning in X for a sec	lda [3],y	;A = end of selection	dey	dey	sta [3],y	;store old end as new beginning	iny	iny	txa	sta [3],y	;store old beginning as new end@okay	pld	pla	pla		rts*** end of 26-Nov-90 DAL************************************************************************ Handler to see if an Appletalk volume has changed.***********************************************************************CheckVolume	phd		;save current d		PushLongSpace		;results	PushWord #0		;system tool	PushWord #$0017		;Standard File tool set	_GetWap	pld		;set DP to old direct page for this routine	pla		;toss upper				lda FileSysID	cmp #AppleShareID	bne exit		;only care about apple share now.	PushLongSpace	_GetTick	PullAX		;results	and #$01FF		;8 seconds	bne exit		;not time	jsr DoGetFileInfo		;get the file info into the ParBlock** see if the data changed (or was never there!)*	ldx #6		;move 4 words	ldy #FileModInfo+6		;destination@4	lda ParmodTD_GFI,x		;mod date and time in a holding location.	cmp [DInfoPtr],y		;see if it changed	bne change		;got a change	dey	dey	dex	dex	bpl @4	bra exit		;leavechange	lda ParmodTD_GFI,x		;move mod date and time into a holding location.	sta [DInfoPtr],y		;copy over the change and the rest	dey	dey	dex	dex	bpl change			sec	ror ztemp3	jsr ReDoList		;force a redrawexit	pld	rts	************************************************************************ Dialog Hook Proc. call***********************************************************************DoHook	lda DilgHook+1		;cheat: not likely both will be 0 if neither word 0	beq ReturnHook		;skip if empty	PushLong DialogPtr	PushZPtr ItemHit	lda #(ReturnHook-1)>>8	pha	lda #ReturnHook-1	and #$00FF	xba	ora DilgHook+2	pha	lda DilgHook	dec a	pha	rtlReturnHook	rtsDoCreate************************************************************************ Create a folder with the passed name****