opModalReturn*********************************************************************** Re-Do the list. Called above and inside re-scan appleshare**********************************************************************ReDoList	_WaitCursor	jsr BuildList		;re-build the list	php	pha	;added 28-Mar-91 DAL	_InitCursor	pla	;added 28-Mar-91 DAL	plp	bcc @1	cmp #$004E		;no access error?	beq @AccessError	sec	bra PassBackError@AccessError	bit ztemp3	bmi ReDoList		;if from re-scan, try again	clc		;no error if access	bra PassBackError		;send back error@1		jsr SetClose		;incase the close button changed		PushZLong DialogPtr	_SetPort		;restore port!		lda FGetPutFlag		;if not multi then the selection bits	and #MultiFileMode		;are still setup correctly	beq NoMulti		PushZLong ListControl1	;List Control Handle	jsr DerefandLock		;returns a pointer to list control record	sta pointer	stx pointer+2		;need a zero page loc for indirect	ldy #octlflag	lda [pointer],y 	and #$FFFD		;reset the list selection bits for multiple selections, 	sta [pointer],y		;just in case they were changed by the "Volumes" list.NoMulti	PushZLong selectedptr	;selected item	PushZLong ListRecPtr	;pointer to list record	_NewList		;ok, do it!		jsr DoPathDraw		;redraw the path too	clc		;no errorPassBackError	rts************************************************************************ Return_File: Will set the Parameters and return the select file.* 'pointer2' points to the name Pstring. (Entry from DoSave or DoOpen).***********************************************************************Return_File	lda FGetPutFlag	bit #MultiFIleMode		;multi file return	beq NotMulti	brl FinishMulti		;we know how many now.NotMulti	ldy #$0002	lda [PrefixPtr],y		;length of original string (with seperator)	sta ztemp1		;save original path length for restore.	ldax pointer2		;name of file pointed to by this string	jsr AddToPrefix		;PrefixPtr contains a string of entite path	ldy #$0002		;a