*-----------------------------------------------------------** Build the name and path for an old call. Return P-String. Pointer2 points to item name Pstring.*FinishOld	ldax ReplyPtr	clc	adc #Oname		;get a pointer to the destination	bcc @10	inx@10	stax pointer		;output pointer into reply record** copy name to output ReplyPtr*	ldy #0015		;move length + 15 characters	shortm		;into short mode@20	lda [pointer2],y	cmp #'/'	bne @21	dec ztemp1		;flag says we have a / in name@21	sta [pointer],y	dey	bne @20		;all but byte containing length	lda [pointer2]	and #$0F		;limit length to 15 characters	sta [pointer]	longm** copy Prefix & name to output ReplyPtr. Convert to P string.*	ldax ReplyPtr	clc	adc #OPath		;get a pointer to the destination	bcc @30	inx@30	stax pointer		;destination pointer into reply record		ldax PrefixPtr	clc	adc #$0003		;first byte of string - 1			bcc @35		;(-1 is WORD length compensation)	inx@35	stax pointer2		;source pointer		ldy #0002		;length of source	lda [PrefixPtr],y		;get length	and #$7F		;128 characters max	tay		;length	pha		;save a copy of the length@40** need to prescan the name for '/' characters*	lda [pointer2]	and #$FF00		;if already '/'. skip this check	cmp #$2F00		;'/' in high byte	beq @41		;just do it if already /	stz ztemp1		;scan flag < 0 if '/' exists in name.	phy		;save the y@42	lda [pointer2],y		;prescan for '/''s	and #$00FF		;if already '/'. skip this check	cmp #'/'	bne @43	dec ztemp1@43	dey	bne @42@41	ply@45	shortm	lda [pointer2],y	cmp #':'		;colons become '/'	bne @44		;ok if not a ':'	bit ztemp1	bmi @44		if '/' in name, skip translation	lda #'/'@44		sta [pointer],y	dey	bne @45	ply		;recall length	tya		;recall length	sta [pointer]		;save length in Pstring		longm		clc		;no error	brl DoExit		;get out now************************************************************************ Finsih Multi select by building the desired data record needed.*