k!*	pla	ldy #0002	sta [PrefixPtr],y		;restore prefix** re-size the handle to include this next entry*	ldy #4	lda [handle],y	and #$7FFF		;drop lock bit	sta [handle],y		;unlocked	ldx #0000		;max handle size here 65k	lda [pointer2]		;size of name string	and #$00FF		;256 character max	clc	adc [pointer]		;current size 	adc #9		;space for prefix, type aux type, string length, string prefix	pha		;save a copy of the "real size	PushAX		;new size	PushZLong handle	_SetHandleSize		;resize handle*	bcsl MainExit	PushZLong handle	jsr DerefandLock		;relock handle	stax pointer	pla		;was the size	sta [pointer]		;current size	ldy ztemp2		;next space	lda ParFileType_GFI	sta [pointer],y		;save file type	iny	iny	ldax ParAuxType_GFI	sta [pointer],y	iny	iny	txa	sta [pointer],y		;file auxtype	iny	iny		;next location	lda [pointer2]		;length of string	and #$00FF		;256 characters max	tax		;save length in x	clc	adc #02		;account for 8:	sta [pointer],y		;string length	iny	lda #':8'		;prefix number (it swaps during the store)	sta [pointer],y	iny	iny		;next place does not really exists yet.@2	longm	incl pointer2		;next character	shortm		;length of string in x	lda [pointer2]	sta [pointer],y	iny	dex	bne @2	longm	sty ztemp2	brl multiloopMultiDone	ldy #0002		;place for handle	ldax handle		;return the handle	sta [ReplyPtr],y	iny	iny	txa	sta [ReplyPtr],y		clc		;no error	brl DoExit		;get out now************************************************************************ Get text from text edit item in PUT dialog. Puts text in memory area* 'NamePtr' and returns a pointer to that text in 'pointer2'***********************************************************************GetTextItem		PushZLong DialogPtr		; the dialog pointer	PushWord #0010		; item 10 = edit box	ldax NamePtr	clc		; put the string where the : will go (over the size)	adc #$0005		; you have to see the picture to understand	bcc @1	inx@1	PushAX		; temp location for file name	stax pointer2		; also into a temp to use later	_GetIText		; get the string	rts************************************************************************ Set up the common part of the reply record for both old an new calls.* Will fille in the Boolean TRUE value, the File type and Aux type entries.** On Exit: Y pointing to the next available slot in the reply record* (filename for old calls, nameVerb for new calls) and CARRY set for OLD calls.** Uses; A,X,Y***********************************************************************CommonReply	lda FGetPutFlag		;set carry for call type	lsr a		;carry = 0 for new call	ldy #Ngood		;index into reply record	lda #TRUE	sta [ReplyPtr],y		;all calls same location in record	iny	iny		;point to FileType	bit FGetPutFlag		;don't change these for put	bmi @2		;skip file type and aux type for put.	lda ParFileType_GFI	sta [ReplyPtr],y	iny	iny		;point to AuxType	ldax ParAuxType_GFI	sta [ReplyPtr],y		;low byte always	bcs @1		;carry set on entry	txa	iny	iny	sta [ReplyPtr],y	bra @1		;and exit@2** Adjust y for items not changed*	iny	iny		;point to AuxType	iny	iny		;point to AuxType 2nd@1	iny		;point to next record	iny	rts	************************************************************************ FinishNew: called to create the output record and fill it with the* necessary information.** INPUT: from various records and d-page variables.*      It is assumed that ztemp1 contains the original length of*      the path in PrefixPtr.** ASSUMPTION: Reply record verbs have already been checked for bad values.** EXIT: If an error occured, CurError contains the error value.*       Uses d-page temps: ztemp2, pointer*       Carry set if errors. Clear otherwise.***********************************************************************FinishNew** First the name. Pointer2 is a pointer to a PString of less than 256 characters.*	ldax [ReplyPtr],NewReplyRecord.NnameRef	;name reference value	stax pointer		;destination	ldy #NewReplyRecord.NnameVerb	;name verb	** legit values for this verb are 0, 1, & 3*	lda [ReplyPtr],y		;verb value	beq @5		;it's a pointer, use it as is	dec a		;1?	bne @2		;ne = new handle please** passed a handle...size it accordingly*	lda [pointer2]		;size of name string	and #$00FF		;byte of size	clc	adc #4		;buffer size and string size words	pha		;save extra copy	ldx #0		;msb of size = 0	PushAX		;push size of handle (long)	PushZLong pointer		;the handle	_SetHandleSize** This could return an error but I will skip it because NameCopy will set the error for me if* it can't fit.*	php		;save carry	PushZLong pointer		;handle for the deref	jsr DerefHandle	stax pointer		;save destination over copy of handle	plp	pla	bcs @5	sta [pointer]	bra @5@2** If here, only original values left are 2 and 3 (now 1 and 2), and 2 was eliminated so * they want a new handle. Go make one the right size.*	lda [pointer2]		;size of string	and #$00FF		;byte of size	clc	adc #4		;buffer size and string size words	pha		;save size	jsr GetZeroHandle	PushAX		;deref it to use it!	stax [ReplyPtr],NewReplyRecord.NnameRef	;give it back to them here	jsr DerefHandle	stax pointer		;save pointer	pla		;size back	sta [pointer]		;save buffer size@5** now copy the name from pointer2 to pointer. Make sure there is enough room too*	lda [pointer2]		;source	and #$00FF		;source length	tay		;guess to # of characters to copy	jsr Name_copy		;copy the string	beq Path_return		;everything is ok!	lda #BadVerbRRName		;name buffer too small	sta CurError		;save errorPath_return** Now the path return. PrefixPtr is a pointer to a C1OutputString much like what* I need here so for the most part this will be just a copy. But first restore PrefixPtr* to its original length.*	ldax [ReplyPtr],NewReplyRecord.NpathRef	;path reference value	stax pointer		;destination	ldy #NewReplyRecord.NpathVerb	;path verb	** legit values for this verb are 0, 1, & 3*	lda [ReplyPtr],y		;verb value	beq @5		;it's a pointer, use it as is	dec a		;1?	bne @2		** passed a handle...size it accordingly*	ldy #0002	lda [PrefixPtr],y	clc	adc #4		;buffer size and string size words	pha		;save extra copy	ldx #0		;msb of size = 0	PushAX		;push size of handle (long)	PushZLong pointer		;the handle	_SetHandleSize	php** This could return an error but I will skip it because NameCopy will set the error for me if* it can't fit.*	PushZLong pointer		;handle for the deref	jsr DerefHandle	stax pointer		;save destination over copy of handle	plp	pla	bcs @5		;if handle error, don't set size!	sta [pointer]	bra @5@2** if here, only original values left are 2 and 3 (now 1 and 2) and original 2 was eliminated so* they want a new handle. Go make one the right size*	ldy #0002		;just how long is needed.	lda [PrefixPtr],y		;size of path	clc	adc #4		;buffer size and string size words	pha		;save size	jsr GetZeroHandle	PushAX		;deref it to use it!	stax [ReplyPtr],NewReplyRecord.NpathRef	;send it back to them here	jsr DerefHandle	stax pointer		;save pointer	pla		sta [pointer]		;save buffer size@5** now copy the path from PrefixPtr to pointer. Make sure there is enough room too.*	ldy #0002	lda [PrefixPtr],y		;source length	pha		;guess to # of characters to copy	sta [pointer],y		;save length	lda [pointer]		;destination buffer size	sec	sbc #0004		;max string that will fit	cmp 1,s		;enough room?	bcs Pcopy_ok		;buffer is plenty large, do it!	ply		;toss away what we wanted to copy	pha		;what we can copy	lda #BadVerbRRPath		;path buffer too small	sta CurError		;save errorPcopy_ok	ply		;bytes to copy	iny	iny	iny		;account for the 4 bytes at front and 0 math.	shortm@3	lda [PrefixPtr],y	sta [pointer],y	dey	cpy #0003	bne @3	longmNewReturnExit	clc		;guess no error	lda CurError	beq @1	sec@1	rts*********************************************************************** special routine