enuBar	pla	sta OldMenuBar	pla	sta OldMenuBar+2	pha	pha	lda #0	pha	pha	_NewMenuBar	lda 3,s	sta PopUpMenuBar+2	lda 1,s	sta PopUpMenuBar	_SetMenuBar	pha	pha	pea 0	pushlong #MyMenuTemplate	_NewMenu2	lda 1,s	sta PopUpMenuHandle	lda 3,s	sta PopUpMenuHandle+2	pea 0	;insert new menu at beginning of bar	_InsertMenu	pha	pha	;space for GetSysIcon (desktop icon)	pea 2	;misc icon	lda #0	pha	;misc icon #0	pha	pha	;aux value (long)	_GetSysIcon	pla	sta theDeskIcon	pla	sta theDeskIcon+2	pea 0	;by pointer	pushlong #MyVolItemTmpl	pea 0	;at beginning of menu	pea 1	;in Menu ID	_InsertMItem2	pea $0004	;open folders, device at bottom	clc	lda <PrefixPtr	adc #2	tax	lda <PrefixPtr+2	adc #0	pha	phx	;pathname pointer (word-length string)	pea 0	;device number (7-Feb-91 DAL)	pea 1	;Menu ID	pea 0	;insert at beginning of menu	pea $0101	;starting Item ID	pushlong #IPMIResults	_InsertPathMItems	rtspathDItemNum	dc.w 0thePathItemBox	dc.w 0,0,0,0MyMenuTemplate	dc.w 0	;version	dc.w 1	;Menu ID	dc.w $0020	;everything is by pointer; XOR drawing	dc.l MyMenuTitle	;empty title	dc.l 0	;no itemsMyMenuTitle	dc.b 0	;null pString*** Here's my Desktop/Disks menu item templateMyVolItemTmpl	dc.w 0	;version	dc.w $0100	;item ID	dc.b 0,0	;key equivalents	dc.w 0	;check mark	dc.w $0420	;item flag (XOR, use ItemStruct for title)	dc.l DeskItemStruct	;copy of the Desktop iconDeskItemStruct	dc.w $8000	;has an icon	dc.l theDeskString	;item nametheDeskIcon	dc.l 0theDeskString	dc.b 5,'Disks'	;25-Mar-92 DALOldMenuBar	dc.l 0PopUpMenuBar	dc.l 0PopUpMenuHandle	dc.l 0theChosenItem	dc.w 0IPMIResultspmHighestID	dc.w 0pmHandle1	dc.l 0pmHandle2	dc.l 0** KillPathMenu*KillPathMenu	pea 1	_DeleteMenu	pushlong PopUpMenuHandle	_DisposeMenu	pushlong PopUpMenuBar	_DisposeHandle	pushlong pmHandle1	_DisposeHandle	pushlong pmHandle2	_DisposeHandle	pushlong OldMenuBar	_SetMenuBar	rts***************************************************