The assumption is that the current path is already pointed to by the* ptr 'PrefixPtr' in a class 1 string** Exit:*   Carry is set if we can't find a drive to change to!*   Carry clear if a new drive was selected or a new volume is*     in the current drive.***********************************************************************NextDrive	** Since NextDrive is ALWAYS is going to be the top level, the following* code will set the directory level to top EVEN if no disk is inserted.* Also pre-zero the number of entries as this will blank the list on a* disk error.** This helps stop a possible bugs.*	lda CurDev	bne @1	rts@1	jsr DirectoryUp	lda topflg	bne @1NextDrive2	lda #0		;say no items	ldy #ListRecord.ListCount	sta [ListRecPtr],y		;number of entries found.** Go get name of current device # and see if the volume name changed*	lda curDev		;starting point	pha		;save it on stack for later check	jsr DoDInfoCall		; get Dev number	bcs Bump		;if an error on occured, next device** now pass that name to _Volume and get the Volume name. Parameter count is still 2*	jsr DoVolumeCall	bcs Bump		;if an error occured, go to next device NOW** compare new name to the one in prefixptr.* check to see if the lengths are different first *	ldy #0002	lda [volName_Volume],y	;length of returned string	sta ztemp1		;hold length	inc a		;pretend it has a seperator!!! (cheat for length check)	cmp [PrefixPtr],y		;see if different length	bne different		;different lengths!	iny	iny		;point to first character		shortmloop	lda [volName_Volume],y	;character;;;	cmp [PrefixPtr],y		;see if same*** 27-Apr-92 DAL -- case-insensitive compare	cmp #'a'	bcc @notLC	cmp #'z'+1	bcs @notLC	and #$df@notLC	sta @cheat+1	lda [<PrefixPtr],y	cmp #'a'	bcc @notLC2	cmp #'z'+1	bcs @notLC2	and #$df@notLC2@cheat	cmp #$77	;*** modified ****** end 27-Apr-92	bne different		;if different, skip the bump	iny	dec ztemp1	bne loop		;keep looking!** if here, they are the same so we can bump the drive #*	longm		;back to long mode*** added support for going backwards thru the drives 17-Mar-93 SS	lda FGetPutFlag	bit #TabBackwards	beq @fwd	dec curDev	lda 1,s	dec a	bra @ok*** end 17-Mar-93 SS@fwd	inc curDev	lda 1,s	inc a@ok	sta 1,s	bra differentBump*** added support for going backwards thru the drives 17-Mar-93 SS	lda FGetPutFlag	bit #TabBackwards	beq @fwd	dec curDev	bra @ok*** end 17-Mar-93 SS@fwd	inc curDev		@ok	lda curDev	cmp 1,s		;see if we came all the way around	bne different	brl errordifferent	longm		;make sure in long mode	jsr DoDInfoCall		;translate # to name	bcc InfoOk		;if no error, this device is OK*** added support for going backwards thru the drives 17-Mar-93 SS	lda FGetPutFlag	bit #TabBackwards	beq @fwd	jsr SetToMaxDev		;restart with highest dev (+1)	bra Bump*** end 17-Mar-93 SS@fwd	stz curDev		;restart with lowest dev (-1)	bra Bump** Entry point for routine NextDrive1. Called by routine ServiceDiskSwitch.* This is called when we want the volume in CURDEV to be rescanned.*	NextDrive1	pha		;pha just to balance stack at the endInfoOk	jsr DoVolumeCall		;get volume name	bcc VolumeOK		;were ok on the volume	cmp #$002e		;disk switched?	bne Bump		;any other error just go to next drive	bra VolumeOK** Now put the new volumename back into PrefixPtr and BuildList Again*VolumeOK1	phaVolumeOK	ldy #0002	lda [volName_Volume],y	;length of returned string	beq Bump		;if 0, bad device (DEBUG***)	sta ztemp1		;hold length	inc a		;count one for end seperator	sta [PrefixPtr],y		;save new length	dec a		;restore a	iny	iny	shortmloop2	lda [volName_Volume],y	;character	sta [PrefixPtr],y		;see if same	iny	dec ztemp1	bne loop2		;keep moving;;;	lda Seperator		;I end my prefixes with a seperator*** changed 6-May-93 DAL/SS -- Separator is not set up at this point, or not always, so use***   whatever we got at the beginning of the volume name.	phy	ldy #4	lda [volName_Volume],y	ply*** end 6-May-93	sta [PrefixPtr],y	longm		jsr SetThePrefix		;reset prefix 8 and 0		bit FGetPutFlag		;if this is Put....	bpl skipit		;skip if get		PushZLong DialogPtr	_SetPort		;make sure the port is set.		PushZLong DialogPtr	PushWord #0011		;Put StatText item	PushZPtr tempRect		;where to store the Rect	_GetDItemBox	PushZPtr tempRect	_InvalRect		;rect is invalid and should redrawskipit	clc		;no error	bra NDExiterror	sec		;error occuredNDExit	lda FGetPutFlag	and #$FFFF-TabBackwards	;clr flag	sta FGetPutFlag	pla		;fix stack (returns original curDev)	rts	;; Reset curDev to the highest device in the current universe. 17-Mar-93 SS;SetToMaxDev	lda #$0005	sta ParBlock		;all 6 parameters back ($11 bytes)	stz statuscode_DStatus	;request device status	PushZPtr ParBlock2		;a place for return of a few bytes	PullAX	stax statlist_DStatus	;will return status here	lda #2	sta rcount_DStatus	stz rcount_DStatus+2	stz devNum_DStatus	@loop	inc devNum_DStatus	PushZPtr ParBlock		;pointer to parameter block	PushWord #$202D		;_D_Status	jsl ProDos_Stack_Entry	;stack based call	bcc @loop	lda devNum_DStatus	sta curDev	rts	************************************************************************ DogetFileInfo. Saves memory by making the getFileINfo call a subroutine.** Inputs: PrefixPtr = current path.** Side Effects: The information in the memory area for ParBlock is lost.************************************************************************DoGetFileInfo		lda #$07		;need 7	sta parBlock		;need to get the file info ($1F bytes)** here, PrefixPtr should point to the volume of interest*	ldax PrefixPtr	clc	adc #0002	bcc @01	inx@01	stax ParPath_GFI	PushZPtr ParBlock		;pointer to parameter block	PushWord #$2006		;_GetFileInfo_C1	jsl ProDos_Stack_Entry	;stack based call	rts	************************************************************************ DoDInfoCall. Saves memory by making the DInfo call a subroutine.* results are plced in the memory allocated at startup and pointed* to by DinfoPtr.** Inputs: curDev = current device number (as set by GetThePrefix)** Side Effects: The information in the memory area for DInfo called* is updates. Any old information is lost.** Returns carry set if an error and a = error #***********************************************************************DoDInfoCall	** but first, I'll do a status to get write protect information*	lda #$0005	sta ParBlock		;all 6 parameters back ($11 bytes)	lda curDev		;current device number	sta devNum_DStatus	stz statuscode_DStatus	;request device status	PushZPtr ParBlock2		;a place for return of a few bytes	PullAX	stax statlist_DStatus	;will return status here	lda #2	sta rcount_DStatus	stz rcount_DStatus+2		PushZPtr ParBlock		;pointer to parameter block	PushWord #$202D		;_D_Status	jsl ProDos_Stack_Entry	;stack based call	stz writeProtect		;guess not write protected	lda ParBlock2		;low word	bit #writeProtBit	beq @1		;not write protected	dec writeProtect@1	lda #08		;get lots of stuff as someone may need it.	sta ParBlock		;8 parameters to DInfo ($15 bytes)	lda curDev		;current device number	sta devNum_DInfo	ldax DinfoPtr	stax devName_DInfo		;a place for the returned name			PushZPtr ParBlock		;pointer to parameter block	PushWord #$202C		;_DInfo_C1	jsl ProDos_Stack_Entry	;stack based call	rts	************************************************************************ DoVolume called a few places above. Leaves info in ParBlock.** This routine also gets the total blocks and total free blocks of the current* drive and saves them in [SizeInfoPtr],y where y is totalSize or totalFree.* In addition, a P-String is made of each value and saved in [SizeInfoPtr],y* where y is totalSizeStr or totalFreeStr. ParamText is called so that the * replacement strings are ready for any dialog that needs them.** Returns carry set if an error and a = error # on the _Volume call.***********************************************************************DoVolumeCall	lda #$0006	sta ParBlock		;all 6 parameters back ($15 bytes)	lda DinfoPtr		;memory for Dev Name Input	clc	adc #2		;Passed the buffer size	sta devName_Volume	lda DinfoPtr+2	adc #0	sta devName_Volume+2	ldax NamePtr		;This will make a good temp location...	stax volName_Volume		;...to put the results	ldy #0002	lda #0000	sta [volName_Volume],y	;0 length (DEBUG)** DEBUG: the above corrects a new porblem on 4.1d8. Volume calls on non block devices* no longer return an error.  I'll detect 0 length on the volume name and skip the device.* Could cause a problem on any real unnamed device.*			PushZPtr ParBlock		;pointer to parameter block	PushWord #$2008		;_Volume_C1	jsl ProDos_Stack_Entry	;stack based call	bcs @notOK	brl statusOK@notOK	cmp #$57		;DAL 6-Jan-91 duplicate volume	beq badvolume		;DAL 21-Apr-91	cmp #$52		;Is it unknown volume error?	beq badvolumeFileSys	cmp #$27		;Is it an I/O error	bne JustReturnError	pha		;Save error code on stack	lda curdev		;Get device number of device we're looking at	asl a	tax	lda StaticDeviceTable,x	beq badvolume2		;error code already on the stack!	pla		;get error back in a-regJustReturnError	sec	brl ErrorOccurred** 6-Jan-91 DAL** Call ErrorWindow and eject the disk.* We do this for Duplicate Volume, and maybe for others later.*ErrorAndEject	pha	;put error on stack so Eject can pull it later	pha	;space for result	pea 0	;substitution type	pea 0	pea 0	;substitution array	pha	;error code	_ErrorWindow	pla	;button number (ignore)	brl EjectThatThang* end of 6-Jan-91 DALbadvolumeFileSysbadvolume	pha		;Save error code.badvolume2	_InitCursor*** added 15-Apr-91 DAL -- let HandleDiskInsert to most of the work for us	pha	;space for result flags	pha	;space for result device number	pea $4000	;handle this insertion	pei <curDev	;devNum input	_HandleDiskInsert	plx	;device number	ply	;result flags	bcs @err	txa	beq @err	;devnum=0 means they ejected--treat it like an error	pla	;kill old error code	brl DoVolumeCall@err	pla	sec	brl ErrorOccurred*** end of 15-Apr-91 DAL** Eject device <curdev (DAL)*EjectThatThang	lda #5	sta ParBlock	lda <curDev	sta devNum_DControl	lda #ejectMedium	sta controlCode	PushZPtr ParBlock		;pointer to parameter block	PushWord #$202E		;_DControl	jsl ProDos_Stack_Entry	;stack based call	pla		;get error code back	sec	brl ErrorOccurred	statusOK	lda ParFileSysID_Volume	sta FileSysID	ldax ParTotBlks_Volume	;total blocks	jsr convert_to_k		;change blocks to K	PushAX		;on the stack for string call (later)	stax [SizeInfoPtr],totalSize	;save total blocks	ldax ParFreeBlks_Volume	;free blocks	jsr convert_to_k		;change blocks to K	PushAX		;free on the stack for string call	stax [SizeInfoPtr],totalFree	;save free size	ldax SizeInfoPtr	sec		;add 1 to leave space for string size	adc #totalFreeStr		;point to place for string	bcc @1	inx@1** total free is on the stack*	PushAX		;destination of string 1;	PushWord #0010		;10 characters;	PushWord #False		;unsigned;	_Long2Dec		;string set up 1	jsr Long2DecTen	;5-Mar-92 DAL** total size should still be on the stack.*	ldax SizeInfoPtr	sec	adc #totalSizeStr	bcc @2	inx@2		PushAX		;destination of string 2;	PushWord #0010		;10 characters;	PushWord #False;	_Long2Dec	jsr Long2DecTen	;5-Mar-92 DAL** scan integer math string and make a P-string*	ldy #totalFreeStr+1	;where the string starts	jsr findspace		;pass spaces** AX contains a pointer to a P-string of total blocks (resides in memory of SizeInfoPtr)*	PushAX		;ParamText needed it here** repeat for free blocks*	ldy #totalSizeStr+1	;where the string starts	jsr findspace		;pass spaces	PushAX	PushLong #0	PushLong #0		;last 2 strings blank	_ParamText	clc		;ignoring errors from conversionErrorOccurred	rts*** Added 5-Mar-92 DAL** Long2DecTen -- call Long2Dec, unsigned, 10-character buffer