ge of temp*** ENTRY TO BUILDLIST IS BELOW EXIT POINT**BuildExit** OK, quiet down. I put the exit up here so it's closer to more branches!!!*	php	pha		;save error status and code (if any)	jsr ClosePrefix		;close this directory		pla	plp	rts**------------------------entry to BuildList-------------------------------------------*BuildList	lda FGetPutFlag		; Clear the flag that says we're currently	and #$FFF7		; displaying the volume list.	sta FGetPutFlag	** step 1, find and open the selected volume*		jsr GetFirst		;Find and open the volume (carry set if error)	bcs BuildExit		;no error returnedAllOk**Step 1.5, dispose of old handle.*	ldax ListPointerHandle	jsr KillHandle		;gets rid of any old handle ** step 2, do a get_dir_entry on the returned volume to get the number of entries*	jsr ReadDirSize		;calls ReadAnEntry with 0,0 for size of directory	bcs BuildExit** size of this directory returned in A as a FIRST guess to the amount of memory needed* for the Name ListManager pointer table. So now we get some memory for the list*	inc a		;this will prevent a 0 from screwing up.	inc a		;a little extra space (Fudge Factor)	pha	asl a		; do times 4 (clear carry too!)	asl a		;X4	adc 1,s		;x5 bytes per entry	plx		;toss away pushed handle** CAUTION: Can't have more than 13,107 files in a directory*	jsr GetZeroHandle		;List pointer memory (will grow if needed)	stax ListPointerHandle	;returns handle to memory which is all 0	PushAx		;push for the derefandlock	jsr DerefAndLock		;returns a pointer to memory	stax ListPointerPtr** so now we have a place to build the Pointers and flags to the List Member's strings.* Except here, instead of actual pointers to the strings, these will be OFFSETS from the* begining of the buffer area. This will allow me to grow the memory area without having* to update all the pointers. Since I am going to do my own custom draw routine, the* List Manager will never need to know about this change!*** so now it's time to build the actual list (First pass is unsorted)*	stz StringsLength		;init length "used" in String array	stz StringsLength+2	;init length "used" in String array	stz StringsOffset		;next element value (start 0)	stz ztemp2		;count of itemsdir_loop		jsr ReadNextDirEntry	;get next entry into [NamePtr]	bcc Rno_error	cmp #$61		;end of directory?	beql Builddone	sec		;set error***DEBUG**, a strange director error occured which was not end of directory. What should* I do with this error? Should I ignore the entry and continue or simply fail?*	bra BuildExit		;simply return errorRno_error	lda ParAccess_GDE		;access of this entry	and #$0004		;bit set	beq NotInvisible	and invisible		;if bit clear, this will result in zero	beq dir_loop		;skip it!Notinvisible	jsr ValidEntry		;see if this is valid and or dimmed	beq dir_loop		;skip this guy	inc ztemp2		;count 1 to display** Add this guy to the list*	lda StringsOffset		;update pointers	sta [ListPointerPtr]	;offset to this string	lda DimmedFile		;need to dim this entry?	bpl NoDim	shortm	lda #MEM_DISABLE+NOT_POSSIBLE	ldy #$0004	sta [ListPointerPtr],y	;disable this item if not folder	longmNoDim	lda ListPointerPtr		;move the pointer forward	clc	adc #$05		;each element is 5 bytes	sta ListPointerPtr		;next slot*** added 21-Dec-90 DAL: Here's the fix for that annoying repeating-entry bug that kept showing up*** (This 4-byte patch has been needed for about 4 years.  Neat, eh?)	bcc @dal1	inc ListPointerPtr+2@dal1*** end of 21-Dec-90 DAL addition	ldy #2		;start of actual string (length)	lda [NamePtr],y	tax		;x gets size of string	lda NamePtr	clc	adc #04		;pointer to start of string	sta NamePtr	bcc @1	inc NamePtr+2		;NamePtr points to start of string@1	jsr ExtendHandle		;size of string in x. See if enough room	bcsl BuildExit		;out of memory** x was preserved in the above call** Now copy the string into the memory area reserved for the strings*	ldy StringsOffset	txa	sta [StringsPtr],y		;copy length to [StringsPtr]	inyBcopy_loop** Note: The following assumption is made here:*   There will be no more than 65k bytes worth of file names (path not included).*   This averages approx 2000 files of 32 characters per file name.*	lda [NamePtr]	sta [StringsPtr],y		;copy string to [StringsPtr]	incl NamePtr		;bump pointer	iny	dex	bne Bcopy_loop		lda FileType	sta [StringsPtr],y		;copy string to [StringsPtr]	iny	iny		;this IS a word** Matt's addition for Claris, add the AuxType after the fle type following the string.*	ldax AuxType	sta [StringsPtr],y	iny	iny	txa	sta [StringsPtr],y	iny	iny******************************************	sty StringsOffset		;save y	PushZLong NameHandle	jsr DerefAndLock	stax NamePtr		;restore the original NamePtr	brl dir_loop		;loop back and store yBuildDone** Now that we have the list lets do something with it (it's still unsorted)** First thing is to change the offsets in the List Manager Ptrs to real addresses* and pass this to the list manager.*	lda ztemp2		;number of entries actually found	ldy #ListRecord.ListCount	sta [ListRecPtr],y		;number of entries found.	lda ListPointerPtr		;low word of next available slot	sta ztemp2		;temp storage location (used below)	PushZLong ListPointerHandle	;go back and get base address of the strings	jsr DerefAndLock	stax ListPointerPtr		;save address of first slot.				lda ztemp2		;last entry - base address	sbc ListPointerPtr	tay		;y = offset to next available slot	phy		;save offset to last.	PushZLong StringsHandle	jsr DerefAndLock		;get base pointer	stax StringsPtr		;might as well put it back again	ply		;restore y** ok, now add the real address of the strings memory to the offsets saved while building the list*ptrupdate	lda [ListPointerPtr],y	;low word	clc	adc StringsPtr	sta [ListPointerPtr],y	iny	iny	lda StringsPtr+2	adc #0		;prop carry	sta [ListPointerPtr],y	tya	sec	sbc #$0007		;-5 and 2 more for iny's above	tay	bcs ptrupdate		;not done yet!		ldax ListPointerPtr		;Save list address in the List Manager's record for get file	stax [ListRecPtr],ListRecord.listPtr	** now sort the list of names (by re-arranging the pointers)**** 25-Mar-91 DAL -- see if it's the Volumes list; use SortList(#1) for regular files	lda <FGetPutFlag	bit #InVolumeList	bne @inVolList	PushLong #1	bra @together@inVolList*** end of 25-Mar-91 DAL	PushLong #CompareRoutine@together	PushZLong ListRecPtr	;pointer to the list	_SortList		;sort list elements	jsr SelectFirst		;select the first possible item	jsr DoGetFileInfo		;set up moddate time info on entry	ldx #6		;move 4 words	ldy #FileModInfo+6		;destination@4	lda ParmodTD_GFI,x		;move mod date and time into a holding location.	sta [DInfoPtr],y	dey	dey	dex	dex	bpl @4	clc		;no carry = no error	brl BuildExit	************************************************************************ Routine used to compare two items as given by the list manager* for sorting. Carry out indicates status of compare.* CC = member A >= member B, CS = member A < member B** Note that this routine is called by the List Manager during the* toolbox call _SortList (as used above). No Standard FIle variables* or local storage are used.** Taken from list manager and modified slightly, this code is now included* here so that upper and lower case names sort as if the case did not matter.**   IN:    PUSH:LONG - pointer to member A*          PUSH:LONG - pointer to member B**  OUT:    Carry***********************************************************************CompareRoutine	DefineStacktempReg	wordstrg1	longstrg2	longorigD	wordRtlAdr	block 3sptr1	longsptr2	long	phd	;save old direct page	tsc	;copy stack ptr to 'A'	sec	sbc #10	;room for temp varible and pen mask	tcs	tcd	;set direct page (to stack)	lda [sptr1]	;"deref" the member pointer	sta <strg1	lda [sptr2]	;"deref" the member pointer	sta <strg2	ldy #2	lda [sptr1],y	sta <strg1+2	lda [sptr2],y	sta <strg2+2		ldy #0	lda [<strg1]	xba	;added 25-Mar-91 DAL (this wasn't working right before)	and #$00FF	cmp #$003A	Is it a colon. If it is then we're in the volume list mode	beq @InVolList	cmp #$002E	bne @notInVolList@InVolList	iny@notInVolList	shortm; begin compare	lop10	tya	iny	cmp [<strg2]	End of gopher string?	beq greater	cmp [<strg1]	beq lessthan	End of current string?	lda [<strg2],y	Grap a byte.	and #$0DF	drop upper case bit	sta tempReg	lda [<strg1],y	and #$0DF	drop upper case bit	cmp tempReg	beq lop10	bra exit10	Carry flag is ready	for exit. greater	sec	bra exit10lessthan	clc	current string < gopher string.exit10	longm; ready to leave;	lda RtlAdr+1		;move the return address down the stack	sta sptr2+2	lda RtlAdr	sta sptr2+1	lda origD		;set the original direct page	tcd	tsc		;start adjusting the stack	php		;but first save the carry bit	clc		;adjust the stack, but don't set it yet	adc #20	plp		;restore the carry bit	tcs		;finish adjusting the stack	rtl		;..and return	************************************************************************ This routine is used to determine if a file is dimmed and or* displayed.** Entry: Uses direct page variables to access information about currently* read file.** Exit: Z flag = true if entry is to be skipped, else entry is ok.*       Direct page variable DimmedFile (actually ztemp1) has dimmed status.** Uses direct page: ztemp1 (aka DimmedFile), ztemp3***********************************************************************ValidEntry	stz DimmedFile		;guess not dimmed.		lda FileType	cmp #$000F		;Folder?	beq GoodFolder		;folders always displayed	sec	ror DimmedFile		;guess dimmed	lda FGetPutFlag		;if Put we dim the rest	bmi good		;forget rest in put	lsr a		;see if old call (leave in carry)** the rest of this routine down to 'Bad' is for Get only, old style type lists*	stz DimmedFile		;back to not dimed again	lda TypeList+1		;is there a Type List? (cheat check)	beq GoodfType		;no type list, check for a routine.** old style type list check. Will need to update this to check Aux types as well*	ldy #$0002		;will point to flags for new calls	lda [TypeList]		;number of entries	bcc NewTypeCheck		;old/new flag bit left in carry	and #$00FF		;up tp 256	beq GoodfType		;silly, but maybe 0 entries!	tay		;scan through the listNextType	lda [TypeList],Y		;Get a type	and #$00FF	cmp FileType		;see if ok type	beq GoodfType	dey	bne NextType*------------------------------------------------------------Bad	lda #00	rts	GoodFolder	lda ParAccess_GDE		;of the folder.	and #$0001		;Do we have read access?	bne AccessOk	ror DimmedFile		;dim the darn folder since you don't have the privileges.** If multifile mode, they may NOT want to display certain folders so I guess they* should be passed to any filter proc if available. This will allow them to skip * certain folders (but why?)*AccessOk	lda FGetPutFlag	bit #MultiFIleMode		;multi-file?	bne GoodfType		;yes, pass this to the filter procGood	lda #True	rtsNewTypeCheck			;a = number of entries (up to 65k)	beq GoodfType		;no type list, continue	tax		;count into x as counter	inx		;cheat so I can pre-decrement	bra NextNewType** the below branch points are to allow me to move forward through the type list record to the next* entry when something does not match in the list.*NExTNewType6	iny	inyNExTNewType4	iny	inyNExTNewType2	iny	inyNExTNewType	dex	beq Bad		;forget it, no match found!	lda [TypeList],y		;flags	sta ztemp3		;save them	iny	iny		;to file type	bit ztemp3		;see if I need to check file type	bvs @1		;nope, wild card file type bit set	lda [TypeList],y		;file type	cmp FileType		;first check!	bne NextNewType6		;file type mismatch, move forward 6 bytes@1	bit ztemp3		;see if I need to check aux type.	bmi GoodfTypeNew		;nope, wild card aux type.	iny	iny		;now check the aux type	lda [TypeList],y	cmp AuxType	bne NextNewType4		;aux type mismatch, move forward 4 bytes	iny		;now check the aux type, word 2	iny	lda [TypeList],y	cmp AuxType+2	bne NextNewType2		;aux type mismatch. move on 2 bytes to next entryGoodfTypeNew** if here, we have a good match on both type and aux (or wild card match of some sort).*	lda ztemp3		;bit 13 says dim this selection	asl a	asl a		;into bit 15	bpl GoodfType		;not set so leave it up to the possible filter proc	sec	ror DimmedFile		;say dimmed	bra Good		;and returnGoodfType** this section only used by Get type calls*	lda FilterProcPtr+1	;is there a User Hook ?(Cheat check)	beq Good		;none, lets get out of here!	pha		;Space for Result in below call		lda FGetPutFlag		;old or new call	lsr a	bcc NewCall		;go do with existing block** old call must create a ProDos look alike entry.*	jsr dir_translate		;create a ProDos look alike block	PushZLong ProDosDirEntry	bra CommonCall		;continue....NewCall	***	PushZPtr ParBlock		;Entry read with GS/OS	pushlong #GDE_ParBlock	;25-Mar-91 DALCommonCall	lda #(ReturnAdr-1)>>8	;Where we return to!	pha	lda #ReturnAdr-1	and #$00FF	xba	ora FilterProcPtr+2	pha	lda FilterProcPtr	dea	pha	rtl		;"jsl" to the user routineReturnAdr	pla		;returned value	bne OkToDisplay		;0 = don't display	brl Bad** return code is 1 = no select or 2 = normal*OkToDisplay	cmp #$0001		;dimmed?	bne Good		;say good	sec	ror DimmedFile		;say dimmed again	brl Good		;and display it.	ENDP************************************************************************ DirTranslate - used to convert the new GS/OS GetDirEntry call to * an old ProDos type call WHEN an old call has a filterProc. I was * originally going to translate everything as close as possible but* old standard file only translates a few items and all apps work OK* there so I'm not going to bother either!!! * * Ok, I'll do it all! (11/14/88)** Uses; dpage temps: handle**********************************************************************dir_translate	PROC EXPORT	ldy #$26		;size of PorDos Dir Entry record	lda #$0000ce_clear_loop 	sta [ProDosDirEntry],y	;clear the entire area to 0	dey	bpl ce_clear_loop	** copy the name from the name pointer to the memory area of the ProDos Block.* The assumption is made here that since a length is stored we don't really care if we* copy over additional garbage as well so we move 16 characters always! 16? Oh yea, I * "fix" the length word to put the size in the right byte and move 8 words which is * faster than 15 bytes and then I put back the length word as it belongs.*	ldy #02	lda [NamePtr],y	xba	sta [NamePtr],y		;sawp length "word"	lda ProDosDirEntry		;need a pointer to the destination	sec	sbc #3		;name location offset to allow use of Y	sta pointer		;temp location as pointer	lda ProDosDirEntry+2	sbc #0	sta pointer+2		ldx #$0008	ldy #0003ce_move_loop	lda [NamePtr],y	sta [pointer],y		;copy over the name	iny	iny	dex	bne ce_move_loop	ldy #02	lda [NamePtr],y	xba	sta [NamePtr],y		;sawp length "word" back as it was.			ldax ProDosDirEntry		;create a pointer to get at the other destinations	clc	adc #PDType	bcc @1	inx@1	stax pointer		;this pointer will track the other items		lda ParFileType_GDE		;GS/OS file type	and #$00FF	sta [pointer]		;file type	ldy #0003		;y as the offset starting at blocks used	lda ParBlocks_GDE	sta [pointer],y		;blocks used	iny	iny	lda ParEOF_GDE		;first 3 bytes of EOF	sta [pointer],y	iny	lda ParEOF_GDE+1	sta [pointer],y	tya	clc	adc #$08		;pass time & date, ver, min_ver.	tay	lda ParAccess_GDE	sta [pointer],y		;low,high Access (but we only need 1 byte...)	iny		;y point to AuxType	lda ParauxType_GDE		;low of aux	sta [pointer],y** now convert the time fields** First, creation time and date*	ldax ProDosDirEntry		;create a pointer to get at the other destinations	clc	adc #PDCreateDate	bcc @2	inx@2	stax pointer		;this pointer will track the other items	*** changed 25-Mar-91 DAL (the GDE parm block is no longer on direct page)***	ldaxzptr ParCreateDT_GDE	;pointer to time and date	ldx #^ParCreateDT_GDE	lda #ParCreateDT_GDE*** end of 25-Mar-91 DAL	stax pointer2	jsr convert_time		;time returned in x and Y	phy	txa	sta [pointer]		;save date	ldy #0002	pla	sta [pointer],y		;save time** Now the mod date and time*	ldax ProDosDirEntry		;create a pointer to get at the other destinations	clc	adc #PDModDate	bcc @3	inx@3	stax pointer		;this pointer will track the other items	***	ldaxzptr ParModDT_GDE	;pointer to time and date	ldx #^ParModDT_GDE	;25-Mar-91 DAL	lda #ParModDT_GDE	stax pointer2	jsr convert_time		;time returned in x and Y	phy	txa	sta [pointer]		;save date	ldy #0002	pla	sta [pointer],y		;save time	rts	ENDP;======================================================================;We call this entry point if the time parameters are setup and need;only to be convert to the ProDOS format.;;Input: GS/OS time field in Get File Info pointed to by [pointer2];       (This could be either createTimeDate or modTimeDate.);;Output: format of time:; ; |<-------- X Register --------->|<-------- Y Register --------->|; |                               |                               | ; |<--high Byte-->|<--low  Byte-->|<--high Byte-->|<--low  Byte-->| ;  _______________________________________________________________; | | | | | | | | | | | | | | | | | | | | | | | | | | | | | | | | |; |    year     | month |   day   |0 0 0|  hour   |0 0|   minute  |; |_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|_|; ;======================================================================convert_time	PROC EXPORT	stz pro_time	stz pro_time+2	;start with a clean slate	ldy #day_GDE	lda [pointer2],y	;day	and #$001F	;5 bits	sta pro_time	;save the day in prodos format	ldy #month_GDE	lda [pointer2],y	;month	and #$000F	;4 bits	asl a	asl a	asl a	asl a	asl a	;shift to correct position	ora pro_time	;month is now happy	sta pro_time	ldy #year_GDE	lda [pointer2],y	;year;;;	and #$007F	;7 bits*** added 29-Jan-92 DAL -- a class-0 year is 40..99 for 1940..1999, 0..39 for 2000..2039*** (return unknown-date/time (all zeroes) for out-of-range dates)	and #$00ff	;year (offset from 1900)	cmp #40	bcc @unknownDate	cmp #139+1	bcs @unknownDate	cmp #100	bcc @yearOK;	sec	sbc #100@yearOK*** end 29-Jan-92 DAL	xba	asl a	;shift year to upper 7 bits	ora pro_time	sta pro_time		ldy #minutes_GDE	lda [pointer2],y	;minutes	and #$003F	;6 bits	sta pro_time+2	ldy #hours_GDE	;hours	lda [pointer2],y	and #$001F	;5 bits	xba	ora pro_time+2	sta pro_time+2	;;;	sta pro_time+2	;redundant, 25-Mar-91 DAL	tay		ldx pro_time		rts*** added 29-Jan-92 DAL@unknownDate	ldx #0	txy	rts*** end 29-Jan-92		ENDP************************************************************************ Scan through the list and select the first possible item that can* be selected. Used in BuildList for a new list and also by UpDown arrow* control if nothing is selected** Changes the contents of 'seletedptr' if an item is available for* selection and sets its select bit. If the list is empty or nothing * can be selected the routine selects nothing and returns with * 'selectedptr' nil. ***********************************************************************SelectFirst	PROC EXPORT** if the list is not empty hilight the first element of the list*	ldy #ListRecord.listCount	lda [ListRecPtr],y		;how many entries in this list	beq looksemptynotempty	pha	asl a	asl a	clc	adc 1,s		;* 5	sta ztemp2	pla		;clean stack	ldy #$FFFF		;look throught list (proper offset to get to first item	shortmkeeplooking	iny	iny	iny	iny	iny	cpy ztemp2		;past end of list	bcs looksempty		;if no items to hilight, just look empty!	lda [ListPointerPtr],y	bit #MEM_DISABLE+NOT_POSSIBLE	;item disabled	bne keeplooking		;find me a selectable slot	ora #MEM_SEL		;set selected bit	sta [ListPointerPtr],y	longm** Need a pointer to hand to _NewList so it selects the right item. Here is another reason* there cannot be more than 13,107 items in the list! (y is a word!!!!!)*	tya	sec	sbc #0004		;pointer to start of this record	clc	adc ListPointerPtr	sta selectedptr	lda ListPointerPtr+2	adc #0000	sta selectedptr+2Exit	rtslooksempty	longm	stzl selectedptr		;no item selected	rts	************************************************************************ Save and Zero the Ref Cons (wonderful thing the list manager, eh?)***********************************************************************	ENTRY SaveAndZeroRefConsSaveAndZeroRefCons	pha		; Get the ref con of the list	pha		; control and save it	PushZLong ListControl1	_GetCtlRefCon	pla	sta ListRefCon	pla	sta ListRefCon+2	lda ListControl1		; now find the handle to the	sta handle		; scroll bar control	lda ListControl1+2		; (it's at the end of the record	sta Handle+2		; used by the list control)	lda [Handle]	sta Pointer	ldy #2	lda [Handle],y	sta Pointer+2	ldy #octlListBar		;a known offset (page 11-9 IIgs Reference Book)	lda [Pointer],y	sta ScrollControl1		;handle of lists control's scroll bar control	iny	iny	lda [Pointer],y	sta ScrollControl1+2	pha		; use this to save and zero	pha		; ref con of the Scroll bar control	PushZLong ScrollControl1	_GetCtlRefCon	pla	sta ScrollRefCon	pla	sta ScrollRefCon+2ZeroRefCons		PushLong #0		;zero the refcon of the list	PushZLong ListControl1	_SetCtlRefCon	PushLong #0	PushZLong ScrollControl1	_SetCtlRefCon	rts	ENDP************************************************************************ These routines sets the state of the close button to enabled or disabled:* The common button entry may be used to set either and depends on the value* of y upon entry.** If the button is already in the desired state no action is taken.* The global variable openButStat is updated to the new state.** Note that similar functions are performed in the filter routine so* that some changes take place as soon as items are hit.** if called at the CommonOpen entry, the state must be in 'a'***********************************************************************SetClose	PROC EXPORT	EXPORT EnableClose	EXPORT DisableClose	EXPORT CommonOpen** set the close button according to the status of topflg**	jsr check_for_top*	lda topflg		;0 = top level	lda FGetPutFlag	and #InVolumeList	bne DisableClose		;needs to be disabled (waste and fall though otherwise)EnableClose	lda #$0000	bra commonCloseDisableClose	lda #$00FF		; item not enabledCommonClose	ldy #0002		; close ID (Get)	cmp closeButStat		; see if the state changed	beq Done		; then skip this, not necessary	sta closeButStat		; save the new status	bra CommonButtonCommonOpen	ldy #0001	cmp openButStat		; see if the state changed	beq Done		; then skip this, not necessary	sta openButStat		; save the new statusCommonButton	pha		; save state	PushLongSpace		; handle will return here.	PushZLong DialogPtr		; the dialog pointer** the item id goes up by 1 if this is PUT and not GET*	jsr PutAdjust	phy		; push item's ID	_GetControlDItem		; get a handle to the open button** returns handle to item on stack. Stack already has the desired state there!*	_HiliteControl		; Make sure it's onDone	rts	ENDP************************************************************************ GetSelected -- will pass through the list managers list and get the*  first item  selected by checking the selected bit.* A pointer to the string selected is returned in A and X* N bit set true if item pointer return NIL.** GetNextSelected -- will return the next selected item AFTER the member* passed in A&X** uses: ztemp3***********************************************************************GetSelected	PROC EXPORT	EXPORT GetNextSelected		lda #0000	tax		;always first itemGetNextSelected	PushLongSpace	PushAX	PushZLong ListRecPtr	_NextMember		;search specified list record for selected item	PullLong ztemp3		;put in temp** if this is 0 nothing is selected.*	lda ztemp3+1		;cheat check for 0	beq @done	ldax ztemp3		;return "handle"	rep #%00000010		;make sure z bit is cleared!@done	rts	ENDP************************************************************************ DirectoryUp -- Step back one directory level. If no levels to* go back to, return same.** Exit: Carry set if a change occured.***********************************************************************DirectoryUp	PROC EXPORT** the assumption is that the current path is already pointed to by the* ptr 'PrefixPtr' in a class 1 string*		ldy #$0002		;length of string	lda [PrefixPtr],y		;get length	clc	adc #$0003		;pass up buffer length and string length - 1	tay		;hold it!	shortm		;****SHORT MODE******	lda Seperator		;current seperation characterloop	dey	cpy #$0004		;if here, we have done whole stirng	beq done		;we are finished if we get here	cmp [PrefixPtr],y		;see if this is a seperation character	bne loop		;keep looking** if here, we found a seperation character. Simply store this as the new string length to backup*	longm		;*******back to long mode	tya	sec	sbc #0003		;subtract off buffer additions	ldy #$0002	sta [PrefixPtr],y		;this shortens the string	jsr SetThePrefix		;reset the prefix	jsr check_for_top		;check for top level	sec	rts		;return up ok (carry clear)done	longm		;*****back to long mode (in case we branched)	stz topflg	clc		;no change flag	rts		ENDP		************************************************************************ DirectoryDown -- Step down one directory level. The name of the*  directory to step to will be indicated by the string selected*  in the list.** On exit, carry set indicates a change took place else the carry * is clear***********************************************************************DirectoryDown	PROC EXPORT** the assumption is that the current path is already pointed to by the* ptr 'PrefixPtr' in a class 1 string and the next level is indicated by* which member of the list is highlighted.*	jsr GetSelected		;find which picked** returns pointer to the selected string in A & X. Returns 0 if nothing sleceted.*	beq @1	PushAX		;convert returned member to string pointer.	jsr DerefHandle		;deref handle	stax pointer2		;pointer to the string	jsr AddToPrefix		;add name to prefix string		sec	ror topflg		;non-0 indicates not top	jsr SetThePrefix		;reset the prefix	sec		;carry set indicates a change took place	rts@1	clc		;carry clear indicvates no change happened	rts	ENDP************************************************************************ See if I am at the root level and set the dpage variable* 'topflg' to non zero if not otherwise zero it. Assumes that a call to* GetThePrefix has already been made so that the dpage variable* 'Seperator' is set correctly.** Uses a,y. Changes topflg**********************************************************************check_for_top	PROC EXPORT	ldy #$0002	lda [PrefixPtr],y		;length of prefix string	clc	adc #$0003		;past buffer again (sheesh!)	tay	stz topflg		;guess we are at the top	shortm	lda Seperator		;get the seperation charloop2	dey	cpy #$0004		;if here, we have done whole stirng	beq done_changed		;we are at the top if we branch	cmp [PrefixPtr],y		;see if this is a seperation character	bne loop2		;keep looking** if we fell through there is still at least another layer left!*	dec topflg		;indicate not top yetdone_changed	longm	rts************************************************************************ Add to Prefix. This routine will add the name in the string* pointed to by A&X to the string already pointed to by PrefixPtr. The* prefix is NOT updated here as this routine is also used to build the* path for the call return (path+file name) as well as just the new prefix.** Uses: ztemp3, pointer2 A, X, Y. Change string pointed to by PrefixPtr***********************************************************************AddToPrefix	PROC EXPORT	stax pointer2		;source location	ldy #$0002		;length of string	lda [PrefixPtr],y		;get last slot 	clc		;get a pointer to the last character (y will point to next)	adc #$0003		;ASSUMPTION, no overflow here!** GS/OS limits path naes to 8K so I know this won't overflow at +4*	adc PrefixPtr		;pointer to end of current string	sta ztemp3		;use D page temp pointer	lda PrefixPtr+2	adc #0	sta ztemp3+2		;upper byte	lda [pointer2]		;get length of string (folder or file)	and #$00FF		;max length is 255	tay	phy		;save a copy of length@loop	lda [pointer2],y	sta [ztemp3],y	dey	bne @loop		;max folder name length is 32K (oh damn!)** add the seperation character*	ply		;recall last character location (from above)	iny		;one past	shortm		;WARNING...last minute change	lda Seperator		;get current seperation character	sta [ztemp3],y		;add the seperation char to the end	longm	tya		;move size added to a	ldy #$00002	clc	adc [PrefixPtr],y		;add length of original string	sta [PrefixPtr],y** probably again should check to see of the path length is greater than 512 (508 actually)* and re-size the handle but again I am being too lazy and we will assume that 508 is* max path size at this time*	rts	ENDP*********************************************************************** * GetFirst -- Find and Open directory of selected volume as indicated* by the device specified by Prefix 8. If Prefix 8 is blank, then* Prefix 0 is taken and copied to Prefix 8.* Assuming the Prefix 8 is small enough, prefix 8 is coppied to Prefix 0.** NOTE: If the entry was from an old standard file call, we start with* with prefix 0 instead. 8 will also get the contents of 0 at this point.***********************************************************************GetFirst	PROC EXPORT	With PopUpGlobals** ASSUMPTION: At this time no prefix can be more than 512 bytes due to size of allocated memory* will need to code to expand this later.*	ldx #$0008		;guess will use 8	lda FGetPutFlag	lsr a		;see if an old call	bcc NotOld	ldx #$0000		;old calls use prefix 0NotOld	txa		;get the prefix needs # in a	jsr GetThePrefix		;get the prefix string	bcs Error		;error, how strange!** Prefix string is now at [PrefixPtr]*	ldy #2		;length of string is after buffer length	lda [PrefixPtr],y	bne OkPrefix		;if non-0, we found a string in #8** yea, I know. I may have already done 0 if this was an old call. No big deal trying again!** (ALREADY 0)	lda #0	jsr GetThePrefix		;8 was unused, try prefix #0	bcs Error** copy 0 to 8 as we need it there. (What if 0 was empty??? Can this happen?)*	lda [PrefixPtr],y		;see if also 0 length	beq Error		;on no, both blankOkPrefix	jsr DoGetFileInfo	lda ParFileType_GFI		;make sure the filetype is a directory FileType	cmp #$000F	bne Error		;if not directory then go to next volume	jsr SetThePrefix		;make 0 & 8 the same.	jsr OpenPrefix		;open the directory specified by prefix	bcc @openOk	cmp #$004E		;was the open error caused by an access error	bne Error** OpenPrefix can return an error (carry will be set if Prefix NOT openend)*@openOk	rts		;return the error flag	** When standard file first comes up we always try to display the list of files for the volume* in prefix 8 or 0. If these prefixes are not valid then we end up here.* Here we try to find the first valid device and display the contents of its directory.*Error	lda #1		;Start search at device number 1.	sta curDev			lda #0		;Force the name currently in prefixptr	ldy #2		;to become invalid.	sta [PrefixPtr],y		;Search for first valid device.	jsr NextDrive2	bcc GotAGoodDrive		;Carry clear means we found one, carry set	brl NoVolumes		;means we didn't and now we must display our;			;"insert a disk..." errow window.GotAGoodDrive		ldx #8		;Since we got a valid device, now we reset	lda FGetPutFlag		;either prefix 8 or 0 to this volume name.	lsr a		;see if an old call	bcc @NotOld	ldx #0		;set prefix 0 for old-style calls@NotOld	stx ParNumber_GetPrefix	lda #2		;pCount	sta ParBlock	lda PrefixPtr	clc	adc #2		;get past buffer size word	sta ParPtr_GetPrefix	lda PrefixPtr+2	adc #0	sta ParPtr_GetPrefix+2	PushZPtr ParBlock		PushWord #$2009		;SetPrefix 8 or 0 to first valid device found.	jsl ProDOS_Stack_Entry		brl GetFirst		;Now try it from the beginning again. 	NoVolumes	stzl selectedptr		jsr PutUpAlert	bcc GotAGoodDrive		rts				*********************************************************************** OpenPrefix will open the file or directory specified in the prefix* string with READ ONLY access. **********************************************************************OpenPrefix	PROC	lda #$0002		;retires on i/o error	sta ztemp1		;will be used as a flagTryAgain	lda #03	sta ParBlock		;3 parameters to Open ($09 bytes)	lda #01		;read access only	sta RequestAccess_Open		ldax PrefixPtr	clc	adc #02	bcc @nocarry	inx@nocarry	stax ParName_Open		;set pointer to path string		PushZPtr ParBlock		;pointer to parameter block	PushWord #$2010		;open	jsl ProDos_Stack_Entry	;stack based call** errors are possible here*	bcc openok** got an error!!!*	cmp #$0027		;i/o error, try again	bne notIOerror	dec ztemp1		;have we tried too many times?	bne TryAgainNotIOerror	cmp #$004E		;no access?	bne anError	pha		;save error	_InitCursor		;Set cursor back to arrow cursor.** access error to this volume. Report the error as a dialog...*..and reset the prefix back "up" one folder level.*	PushWordSpace		;results for alert window	PushWord #0		;indicate C string	PushLong #0		;no substitution string	PushWord #$82		;no access	_ErrorWindow	pla		;don't care what comes back	jsr DirectoryUp		;step the name back out of the prefix	pla		;error saved aboveanError	sec	rts	openok	lda ParRefNumber_Open	sta RefNumber	rts*********************************************************************** ClosePrefix will close the file or directory specified by the reference* number stored in the GLOBAL value RefNumber (usually last opened). An alternate entry,* CloseA will allow one to pass a reference number in A and have that* item closed. The Global RefNumber in this case is unchanged.**********************************************************************	EXPORT CloseA	EXPORT ClosePrefixClosePrefix	lda RefNumber		;Reference number to closeCloseA	tax		;14-Jan-91 DAL (just being paranoid!)	beq @NeverCloseZero		;14-Jan-91 DAL (just being paranoid!)	sta  ParRefNumber_Open	lda  #01	sta  ParBlock		;1 parameters to close		PushZPtr  ParBlock		;pointer to parameter block	PushWord  #$2014		;_Close_C1	jsl  ProDos_Stack_Entry	;stack based call@NeverCloseZero** errors are possible here **DEBUG** What do I do with an error on a close?** I'll ignore it!*	clc		;it never happened!!!	rts	ENDP*********************************************************************** ReadDirSize will return the directory size from the currently opened* directory (as last opened by OpenPrefix above) referenced by the* RefNumber stored in the GLOBAL varaible RefNumber** Size returned in A and also stored the GLOBAL variable DirSize**********************************************************************ReadDirSize	PROC EXPORT	lda #$06	sta ParPCount_GDE	stz ParBase_GDE	stz ParDisplacement_GDE	;0 & 0 will return size of directory	lda RefNumber	sta ParRefNumber_GDE	;currently opened directory	ldax NamePtr	stax ParName_GDE	***	PushZPtr ParBlock		;pointer to parameter block	pushlong #GDE_ParBlock	;25-Mar-91 DAL	PushWord #$201C		;GetDirEntry_C1	jsl ProDos_Stack_Entry	;stack based call** errors can be returned here*	bcs @ohno		;returning here will cause a blank list	@readok	lda ParEntryNum_GDE	;size of directory	sta DirSize@ohno	stz EntryNum		;make sure this is 0	rts	*********************************************************************** ReadNextDirEntry will read the next entry from the currently opened* directory (as last opened by OpenPrefix above) referenced by the* RefNumber stored in the GLOBAL varaible RefNumber.***********************************************************************	EXPORT ReadNextDirEntryReadNextDirEntry	lda EntryNum	cmp DirSize	bge @too_many		;in case network device and size grew	lda #$01	sta ParDisplacement_GDE	sta ParBase_GDE***	lda #13	lda #17		;pCount=17 (25-Mar-91 DAL)	sta ParPCount_GDE		;13 entries	lda RefNumber	sta ParRefNumber_GDE	ldax NamePtr		;place to put the answer	stax ParName_GDE***	PushZPtr ParBlock		;pointer to parameter block	pushlong #GDE_ParBlock	;25-Mar-91 DAL	PushWord #$201C		;GetDirEntry	jsl ProDos_Stack_Entry	;stack based call	bcs @error** errors can be returned here*	lda ParFileType_GDE	and #$00FF		;file types are bytes	sta FileType		;save file type in global	lda ParauxType_GDE	sta AuxType	lda ParauxType_GDE+2	sta AuxType+2	lda ParEntryNum_GDE	sta EntryNum		;current entry number@error	rts		;return error status@too_many	sec	lda #$61		;fake end of directory	rts*** added 25-Mar-91 DAL	export GDE_ParBlockGDE_ParBlock	export ParPCount_GDEParPCount_GDE	dc.w 0	export ParRefNumber_GDEParRefNumber_GDE	dc.w 0	export ParFlags_GDEParFlags_GDE	dc.w 0	export ParBase_GDEParBase_GDE	dc.w 0	export ParDisplacement_GDEParDisplacement_GDE dc.w 0	export ParName_GDEParName_GDE	dc.l 0	export ParEntryNum_GDEParEntryNum_GDE	dc.w 0	export ParFileType_GDEParFileType_GDE	dc.w 0	export ParEOF_GDEParEOF_GDE	dc.l 0	export ParBlocks_GDEParBlocks_GDE	dc.l 0	export ParCreateDT_GDEParCreateDT_GDE	dc.l 0,0	export ParModDT_GDEParModDT_GDE	dc.l 0,0	export ParAccess_GDEParAccess_GDE	dc.w 0	export ParAuxType_GDEParAuxType_GDE	dc.l 0		;old SF only had 13 parms	export ParFileSysID_GDEParFileSysID_GDE	dc.w 0	export ParOptList_GDEParOptList_GDE	dc.l OptionListBuffer	export ParResourceEOF_GDEParResourceEOF_GDE	dc.l 0	export ParResourceBlk_GDEParResourceBlk_GDE	dc.l 0		;now we have all 17OptionListBuffer	dc.w 64	ds.b 64*** end of 25-mar-91 DAL	ENDP	************************************************************************ GetThePrefix** Puts the prefix # passed in A into a class 1 string pointed to by * PrefixPtr and clobbers the data currently in the global ParBlock * (which is where the string resides).** This routine will also update the direct page variable 'curDev' with* the device number that this prefix represents (unchanged if the prefix* is blank).** SetThePrefix** Puts the prefix string in the global ParBlock pointed to by PrefixPtr* into the prefix number 8 and, if it fits, 0.***********************************************************************	GetThePrefix	PROC EXPORT** Puts path name into Reply buffer for passed in A** equates for GetDevNumber*devName	equ ParBlock+02		;Ptr to Device namedevNumber	equ ParBlock+06		;returned dev number	sta ParNumber_GetPrefix	;which prefix	lda #02	sta ParBlock		;Pcount	lda PrefixPtr		;memory for path results	sta ParPtr_GetPrefix	lda PrefixPtr+2	sta ParPtr_GetPrefix+2	PushZPtr ParBlock		;pointer to parameter block	PushWord #$200A		;GetPrefix	jsl ProDos_Stack_Entry	;stack based call	bcs Done		;if an error** Note: This should check the length of the returned string and if longer than the* current buffer size (pointed to by PrefixPtr), we need to re-size the buffer and* issue the call again. But for now 512 bytes should be plenty long.*	ldy #0002		;current length of string loc	lda [PrefixPtr],y	beq done		;skip rest of this string is empty** if not an empty prefix, set curDev to the device # specified by this volume name*	pha		;save the original length.	iny	iny	shortm	ldx #0001		;use as a temp count	lda [PrefixPtr],y		;get current seperation character	sta Seperatorloop	iny		;start with next character	inx	cmp [PrefixPtr],y		;look for seperation character	bne loop		;it's there!	longm	ldy #0002		;save length for volume only	txa	sta [PrefixPtr],y		;put the temp length in the string	lda PrefixPtr		;memory for path results	clc	adc #2		;Passed the buffer size	sta DevName	lda PrefixPtr+2	adc #0	sta DevName+2	lda #0002	sta ParBlock		;2 parameters	jsr GetAndFixPrefs		;added 29-Jan-92 DAL (don't prompt for disk)	PushZPtr ParBlock		;pointer to parameter block	PushWord #$2020		;GetDevNumber	jsl ProDos_Stack_Entry	;stack based call	php		;added 29-Jan-92 DAL	_SetSysPrefsGS oldPrefs	;added 29-Jan-92 DAL	plp		;added 29-Jan-92 DAL	pla	ldy #0002	sta [PrefixPtr],y		;restore original length		bcs Done		;in case an error was returned		lda devNumber		;returned value	sta curDev		;save in global!		clc		;make sure no error reporteddone	rts*** added 29-Jan-92 DAL -- don't prompt for the boot diskGetAndFixPrefs	_GetSysPrefsGS oldPrefs	lda >oldPrefs+2	and #$1fff	;	sta >myPrefs+2	_SetSysPrefsGS myPrefs	rtsoldPrefs	dc.w 1	;1 parameter	dc.w 0	;the old SysPrefsmyPrefs	dc.w 1	dc.w 0	;my modified preferences*** end 29-Jan-92	EXPORT SetThePrefix	EXPORT Force0		;entry to skip size check.SetThePrefix	ldy #$0002		;length of prefix	lda [PrefixPtr],y** A = size of prefix we want to put into 8. If small enough, we will put it back into 0 as* well, if too big, will warn the user and not change*	cmp #$0040		; max size of prefix 0 (64 char)	bcc Force0		; will fit into 0** warn the person if we came in through an old call that this may not work*	ldx #$0008		;also, we skip 0 because we know it's too big	lda FGetPutFlag	lsr a		;if carry set, this old mode	bcc AndAgain		;don't care in new mode, just don't do 0** by the way, simply don't do this and stay where we are as well!*	PushWordSpace		;results for alert window	PushWord #0		;indicate C string	PushLong #0		;no substitution string	PushWord #$88		;Pathname too long	_ErrorWindow	pla		;don't care what comes back	jsr DirectoryUp		;and back this mess out!	sec		;not really an error	rts		;no changeForce0	ldx #$0000		;set prefix 0 first, then do 8AndAgain	phx		;save for later check	stx ParNumber_GetPrefix	;which prefix	lda #02	sta ParBlock		;Pcount	lda PrefixPtr		;memory for path results	clc	adc #2		;Passed the buffer size	sta ParPtr_GetPrefix	lda PrefixPtr+2	adc #0	sta ParPtr_GetPrefix+2	PushZPtr ParBlock		;pointer to parameter block	PushWord #$2009		;SetPrefix	jsl ProDos_Stack_Entry	;stack based call	bcs Oppss	pla	bne Setdone		;we are done?	ldx #$0008		;now do 8	bra AndAgain** Errors returned through call*Oppss	plx		;return an errorSetdone	rts		ENDP		************************************************************************ Misc stuff	***********************************************************************GetLocInfo	PROC EXPORT 		PushWord #00	_GetMasterScb	pla	and #$80	;if bit set, we are 640, else 320	rts		************************************************************************ MoveDialogToMemory -- allocates and locks a memory area in which to* place the current dialog header. Since old standard file calls* have a dialog items that now do nothing, this will Mung out the unused items* by building a new dialog template header list WITHOUT the two unused items;* Namely, "files" and "scroll"* In addition, it needs to add 'PathDraw' to the Path item (if nothing there)* on Patched dialogs.** This also moves the list manager record into RAM as well & updates that * area with the proper rectangle.*** ENTRY: AX points to the dialog template** Exit: AX pointes to the ram area that contains the corrected dialog.** Side effects: Memory is allocated and used. Memory errors may be returned.***********************************************************************MoveDialogToMemory	PROC EXPORT	IMPORT ListManagerRec,OrigDialogTempPtrdestptr	equ pointer	;temp usage, destinationsrcptr	equ pointer2	;temp usage, source dialog pointertmppointer	equ handle	;temp usage, an extra pointer	stax srcptr	;save a copy as of source	sta >OrigDialogTempPtr	;added 15-Sep-91 DAL	txa	sta >OrigDialogTempPtr+2** Move the List manager Record into ram (so it can be updated)*	PushLong #ListManagerRec	;source(pointer)	PushZLong ListRecHandle	;destination(handle)	PushLong #40		;move 40 bytes	_PtrToHand		;move 	bcc NoError		;Oh No**DEBUG. Do I need to worry about this error or can I just die?*	rtsNoError	lda #MultiFIleMode	bit FGetPutFlag		;multi mode	beq NoMulti	ldy #ListRecord.listFlags	lda [ListRecPtr],y		;current flags	and #$FFFD		;Set list manager flag to allow 	sta [ListRecPtr],y		;multiple selections to be made. NoMulti	** prescan to figure the size of this header and allocate some memory to it.*	ldy #0014+1-4	;beginning of dialog item list (low byte + 1 byte offset)@1	iny	iny	iny	;We're checking bytes 1 and 2 of the pointer and if they're	iny	;zero we assume this is not a valid ptr and we're at the end.	lda [srcptr],y	;if this is 0 we are at the end of the list** cheat by looking at bank and page byte which should never be zero unless a template* somewhow got into absloute zero page which should never happen!*	bne @1	;keep looking** y = number of entries * 4. We will be moving 2 less items. We need to allocate a block* of memory of (y-8)+14 bytes.* Note that the new Multi entry moves one of these 2 so this* could be wrong. I'll be safe rather than sorry and since another 28 bytes won't really make* that much difference in the total memory used, I'll forget all this silly stuff and just use* y+14. (Changed 2/17/89)*	tya	;recall # * 4*	sec*	sbc #0008	;subtract out start value. 'A' = (# items * 4) + 14 - 8	jsr GetSmallHandle	;get me some memory	PushAX	jsr DerefAndLock	;lock it down please	stax destptr	;put it on the stack for return	PushAX	;save a copy that will not change (pulled below)** move the standard header.*	lda #0014	;move the first 14 bytes always	jsr moveit	;move rect and flags always		ldx #0000	;move itemsmoveloop	inx	;count next item	txy	;cheat to check for different items to skip** Move the put dialog. Walk the list till 0 is found and skip items 6 & 8.* However, item 7 (files), move the bounding rect to the List Manager Record* Move the get dialog. Walk the list till 0 is found and skip items 5 & 7.* unless this is multi get then leave item 5 (this is the ACCEPT button)* However, item 6 (files), move the bounding rect to the list manager record.* If get, we can cheat the compare by doing an INY for GET so it checks against the same item #'s*	lda FGetPutFlag	bmi @1	;0 = Get, 1 = put	iny	;put is 1 higher in the id so bump Get to match@1	bit #MultiFIleMode	;in multi mode, do item 5	bne @11	cpy #0006	;Put: skip #6 (scroll) and #8 (Files)	bne @11	brl skipthis@11	cpy #0008	;files entry contains list manager rect.	beql moverect	bit #PatchedFlag	;patched?	beq @4** if path item on patched is not already pointing to a draw routine, fix it!*	cpy #0007	;path #7?	bne @3	;skip fix	phx	phy	PushZlong srcptr	jsr DerefHandle	stax tmppointer	ldy #0013	lda [tmppointer],y	;see if set	bne @2	dey	ldax #PathDraw	sta [tmppointer],y	txa	iny	iny	sta [tmppointer],y		;move in draw routine		lda FGetPutFlag		;set flag that says upon exit we need	ora #PathDrawPatched	;to unpatch this field in the user's template	sta FGetPutFlag@2	ply	plx@3** Set item type of prompt string to StatText+Disable*	cpy #0009		;change prompt to StatText	bne @4	phx	PushZlong srcptr	jsr DerefHandle	stax tmppointer	ldy #0010	lda #StatText+ItemDisable	sta [tmppointer],y		;change item type	plx@4** Item 10 in put needs the maxlen set in the dialog template. This HAS to be done here as* SetDItemValue cannot be used (LeNew is called at GetNewModalDialog time and SetDItemValue* cannot be called until AFTER GetNewModalDialog and by that time it's too late!*	bit FGetPutFlag	bpl @41	cpy #0010	;item 10 in edit needs the length "fixed"	bne @41	phy	phx	PushZlong srcptr	;moves along with the source and points to item 10	jsr DerefHandle	stax tmppointer	ldy #0016	;userItem location!	lda MaxLen	;max number of characters	sta [tmppointer],y	;save it!	plx	ply@41** one to include*	lda #0004	;now move these 4 bytes (pointer to the item)	jsr moveit	;move and update pointers (return 0 if we moved all 0's)	bnel  moveloop	PullAX	;recall dest address and return	rts	;we are doneskipthis	lda #0004	;skip 4 bytes from source!	clc	adc srcptr	sta srcptr	bcc @1	inc srcptr+2@1	brl moveloopmoverect** this item is skipped but we want the bounding rect moved to the list manager.*	phx	lda [srcptr]	clc	adc #0002	;1 past item number to bounding rect	sta tmppointer	;use this a s a temp	ldy #0002	lda [srcptr],y	adc #0	;in case of carry	sta tmppointer+2	;use this a s a temp	ldy #0006	;move 8 bytes@1	lda [tmppointer],y	sta [ListRecPtr],y	dey	dey	bpl @1** this is also a good place to calculate the number of visible items: ((top-bottom)-2)/10*	PushLongSpace	;2 words returned	ldy #0004	;bottom position	lda [tmppointer],y	;bottom	sec	sbc [tmppointer]	;difference*	sec	sbc #0002	pha	;dividend	PushWord #0010	;divisor	_SDivide	pla	;quotient	plx	;toss remainder..don't care** place this results at ListManagerRecord + 10 bytes*	ldy #0010	sta [ListRecPtr],y	;# of visible items		plx		bra skipthis	;and bump source pointer and continue	*-------------------------------------------------------------------Moveit** move count bytes from Source memory to Destination and update pointers* This is used to "rebuild" pieces of the dialog template in memory.* ASSUMPTIONS: Always moves an even number of bytes.**Input:  A = count of bytes. srcptr and destptr are zero page temps used.** Output: a = inclusive or of all bytes moved (for zero test)*	pha		;saved for add below	tay		;count in y	dey		;move from 0!	dey	stz ztemp1		;inclusice or register@1	lda [Srcptr],y	sta [Destptr],y	ora ztemp1	sta ztemp1		;will be 0 if we move all 0's	dey	dey	bpl @1	lda 1,s		;recall count	clc	adc srcptr	sta srcptr	bcc @2	inc srcptr+2@2	lda 1,s	clc	adc destptr	sta destptr	bcc @3	inc destptr+2@3	pla		;toss away count	lda ztemp1		;set z flag	rts	ENDP	************************************************************************ GetZeroHandle -- Gets a small hunk of memory < 64K and sets it to zero.*                  Size is passed in A.***********************************************************************GetZeroHandle	PROC EXPORT	pha		;save size	jsr GetSmallHandle		;handle returned in A & X	bcs @error		;skip the rest and return the error	stax handle		PushAX	jsr DerefandLock		;this doesn't use zero page handle or pointer	stax pointer	ply		;this big!!!!!!	dey	shortm	lda #0@loop	sta [pointer],y	dey	bne @loop	sta [pointer]		;don't forget last byte (the count may have been - Dave!!!)	longm	ldax handle@error	rts	ENDP************************************************************************ GetSmallHandle -- Get a hunk of memory < 64K. Size passes in A.***********************************************************************	GetSmallHandle	PROC EXPORT** getting a handle of size smaller than 64K*	ldx #0		;make sure x is 0;;fall through to GetNewHandle;	************************************************************************ GetNewHandle-- Get a hunk of memory. Size passes in A (lo) and X (hi)***********************************************************************	EXPORT GetNewHandleGetNewHandle		PushLongSpace		; Output : Handle. (reserve space)	PushAX		; Block Size.	stax LastRequest		; save for debug, how much did I need	PushWord MyID		; Owner.	PushWord #00		; not purgeable !	PushLongSpace		; Anywhere.	_NewHandle	bcs @error	PullAX		;handle into a and x	rts		@error** DEBUG** This is a real problem. If I get a memory error trying to get a new handle.* Suggestions?*	ply	ply	rts		;carry (error) returned from new Handle************************************************************************ ExtendHandle -- Check if a recently allocated handle needs to grow.* Handle assumed to be in GLOBAL variable StringsHandle at entry* Next size to add is in X. Will check here and expand if more room is needed.* The logicalsize of the handle is in the GLOBAL StringsLength* x is preserved***********************************************************************	EXPORT ExtendHandleExtendHandle	phx		;preserve x	txa	clc	adc #$08		;flag byte, type 2 byte, 4 aux type bytes, size byte			;(can do this since we know string length is ALWAYS < 256)	clc	adc StringsLength		;new size needed	sta StringsLength	bcc @1	inc StringsLength+2@1	ldy #4	lda [StringsHandle],y	and #$7FFF		;drop lock bit	sta [StringsHandle],y	;unlocked	PushLongSpace		;space for results	PushZLong StringsHandle	_GetHandleSize		;so how big is it?	PullAX		;size of handle	cmpl StringsLength		;see if enough room	bge @ok		;still enough room	ldax StringsLength	clc	adc #$200		;grow by 512 bytes	bcc @nocarry	inx@nocarry	PushAX		;new size	stax LastRequest	PushZLong StringsHandle	_SetHandleSize	bcs Abortexit@ok	PushZLong StringsHandle	jsr DerefAndLock		;relock handle	stax StringsPtr	plx		;save x	clc	rtsAbortexit** an error occured, handle not resized. Out of memory...now WHAT??????????????*	plx	rts		;return with error			ENDP*********************************************************************** Kill a handle ... handle passed in A and X**********************************************************************KillHandle	PROC EXPORT	PushAX	_DisposeHandle		rts	ENDP*********************************************************************** Kill a pointer... pointer passed in A and X**********************************************************************KillPointer	PROC EXPORT	PushLongSpace	PushAX	_FindHandle		_DisposeHandle		rts	ENDP****************************************************************** DerefandLock* Input: 	Handle on stack** Handle	LONG** Lock the handle to the list* Value returned in A and X.******************************************************************DerefandLock	PROC EXPORT	DefineStackorigD	word	;reserve word on stackOrts	wordHandlel	long	;reserve long on stack	phd	tsc	tcd	;stack is direct page now (a cheap trick, eh?)		ldy #4	lda [Handlel],y	ora #$8000	;cheat to lock handle.Is this illegal?	sta [Handlel],y	dey	dey	lda [Handlel],y	tax	lda [Handlel]	sta Handlel+2	;save the low word of the pointer on top of the passed handle	pld	;restor direct page	ply	;save rts address	pla	;get rid of the low word of the handle	pla	;get back the low word of the pointer and clean up the stack	phy	;push the return addr back on the stack	rts	;leave this place !		ENDP****************************************************************** DerefHandle* Input: 	Handle on stack** Handle	LONG** DeRef a handle and return in A&X******************************************************************DerefHandle	PROC EXPORT	DefineStackorigD	word	;reserve word on stackOrts	wordHandlel	long	;reserve long on stack	phd	tsc	tcd	;stack is direct page now (a cheap trick, eh?)		ldy #2	lda [Handlel],y	tax	lda [Handlel]	sta Handlel+2	;save the low word of the pointer on top of the passed handle	pld	;restor direct page	ply	;save rts address	pla	;get rid of the low word of the handle	pla	;get back the low word of the pointer and clean up the stack	phy	;push the return addr back on the stack	rts	;leave this place !		ENDP	************************************************************************ CONVERT reference and RELEASE reference routines:************************************************************************* Convert reference and verb to a pointer to a PString for Prompt string* (local use to all above entry points)* EXIT: Pointer to PString in A & X***********************************************************************get_prompt_ptr	PROC EXPORT	EXPORT get_name_ptr	EXPORT name_release	EXPORT prompt_release		clc	PushZLong PromptPtr		;save pointer;	and #$0003	;removed (and it wasn't even in the right place!) 22-Mar-93 SS	lda PromptVerb	beq ItsAPointer		;if a pointer already, return it	dec a		;1 = handle	beq ItsAHandleOnStack	ldy #$8006		;2 = ResourceItsAResource	PullAX	PushLongSpace	phy		;resource type (DEBUG?)	PushAX		;ref	_LoadResource	tay		;save error	PullAX	bcc ItsAHandle		;resource error, exit	tya	bra gExitItsAHandle	PushAX		;back on stack!ItsAHandleOnStack	jsr DeRefAndLock		;get a pointer to PStringgExit	rtsItsAPointer	PullAX		;pointer to PString	rts************************************************************************ Convert reference and verb to a pointer to a C1InputString for default name* (local use to all above entry points)***********************************************************************get_name_ptr	PushZLong OrigName	lda OrigNameVerb	beq ItsAPointer	dec a	beq ItsAHandleOnStack	ldy #$8005		;resource type (DEBUG)	bra ItsAResource************************************************************************ Release if PromptPtr was a handle or a resource***********************************************************************prompt_Release	ldax PromptPtr	stax pointer		;incase it was a handle	ldy #$8006		;ID if a resource	lda PromptVerb;	and #$0003	;removed 22-Mar-93 SS	bra Release************************************************************************ Release if OrigName was a handle or a resource***********************************************************************name_Release	ldax OrigName	stax pointer		;incase it was a handle	ldy #$8005		;ID if a resource	lda OrigNameVerb*	bra Release************************************************************************ Release common.* ENTRY: A = verb. CC = results of loading verb.*        Y = Resource Type.  (pointer) = original passed reference.** EXIT: Pointer unlocked. Carry set for error.***********************************************************************Release	clc		;no error	beq RExit		;pointer, forget it	dec a	beq UnlockIt		;it's a handle, unlock it	pea $0003	phy	PushZLong pointer	_ReleaseResource	rtsUnlockit	ldy #$0004	lda [pointer],y	and #$7FFF		;drop lock bit	sta [pointer],y		;unlockedRExit	rts		ENDP************************************************************************ reset_vars: sets to 0 all variables that MAY not be set when the* tool is reentered. This prevents a cutsom proc routine from being* called (for example) in a standard, no proc call.*********************************************************************** reset_vars	PROC EXPORT	stzl FilterProcPtr	stzl PromptPtr		stzl TypeList	stzl IconHookPtr	stzl DilgHook	stz PromptVerb	stz OrigNameVerb		;default verbs to pointers	stz FRedraw	rts*********************************************************************** will adjust the dialog item number up one if we are in a Put dialog.* (most items are one off because Put has SAVE as #1.** Input: Y = item number** Output: Y = adjusted item number***********************************************************************PutAdjust	PROC EXPORT	bit FGetPutFlag	bpl @1	iny		;put is 1 higher in the id.@1	rts	ENDP	******************************************************************* MyDraw** This routine draws the list item when asked by the list mgr**       Ptr to Bounding Rect*       Ptr to member's record*       Handle to list Control record** Checks 'IconHookPtr' and if not nil, will use that routine to* draw the line item rather than local code. The line item is passed* a pointer to the the list member which is a pstring followed by* a word of file type and a longword of Auxtype.*******************************************************************MyDraw	PROC EXPORT***	with IconGlobals		DefineStackFgetPutCpy	wordTempDpPtr	longoldmask	block 8atempptr	longorigB	byteorigD	wordRtlAdr	block 3CHandle	longMemberPtr	longRectPtr	long	phd	;save old direct page	phb	;save data bank	phk	;push program bank	plb	;set data bank to same as program bank	tsc	;copy stack ptr to 'A'	sec	sbc #0018	;room for temp varible and pen mask	tcs	tcd	;set direct page (to stack)		PushLongSpace		;results	PushWord #0		;system tool	PushWord #$0017		;Standard File tool set	_GetWap	PullLong TempDPPtr		;local use, I need access to my Direct Page	ldy #FGetPutFlag	lda [TempDpPtr],y	sta FgetPutCpy		;get a copy, we need this alot here	pei RectPtr+2	pei RectPtr	_EraseRect	;clear the space		PushZLong MemberPtr	jsr DerefHandle	stax atempptr	PushAX		;on the stack for the possible hook routine		lda FgetPutCpy	and #InVolumeList	bne NoItemHook		ldy #IconHookPtr	lda [TempDpPtr],y	iny	iny		;y=iconHookPtr+2	ora [TempDpPtr],y		;empty pointer?	beq NoItemHook		;skip if empty	lda #(ItemReturnHook-1)>>8	;6 bytes needed (3 "dest", 3 return)	pha	lda #ItemReturnHook-1	and #$00FF	xba	ora [TempDpPtr],y		pha	dey	dey	lda [TempDpPtr],y	dec a	pha	rtl		;go do user hookNoItemHook	PullAX		;didn't need this!*** This is Standard File's default member-draw routine** Set up for DrawIcon call (they are really icons again!)*	lda FgetPutCpy	and #InVolumeList	beq @notInVolumeList		lda [atempptr]	and #$00FF	inc a	tay	lda [atempptr],y*** Now uses GetSysIcon (15-Jan-91 DAL)	pha	pha	;space for GetSysIcon result	pea 1	;device icons	pha	;device ID	lda #0	pha	pha	;aux value (long)	_GetSysIcon	brl do_icon@notInVolumeList	lda [atempptr]	;size of string	and #$00FF	;offset	tay	iny	lda [atempptr],y	;this member's file type	pha	pha	;space for _GetSysIcon	pea 0	;files, closed folders	pha	;filetype;;;	lda #0;;;	pha;;;	pha	;aux value (long)*** 5-Oct-92 DAL -- pass the real auxiliary type	iny	iny	lda [atempptr],y	;low word of auxtype	tax	iny	iny	lda [atempptr],y	;high word of auxtype	pha	phx*** end 5-Oct-92	_GetSysIcondo_icon	pea 0	;mode for _DrawIcon	ldy #2	lda #4	;move over space for 640 mode	jsr mDrawHalfIf320	;12-Jan-91 DAL	clc*** 15-Sep-91 DAL -- moved ADC up here and forced sum to be even	adc [RectPtr],y	;left position of rect	and #$fffe	;force even*** end 15-Sep-91*** added 26-Aug-91 DAL -- set carry if window position is odd, to make dithering right	pha	phy	pha	pha	;space for GetPort	_GetPort	phd	tsc	tcd	lda [3]	and #$0080;;;	clc	;assume CLC from the GetPort call	beq @ok	ldy #10	;offset to boundsRect.left	lda [3],y	lsr a@ok	pld	pla	pla	;discard port pointer	ply	pla*** end 26-Aug-91 DAL -- carry is set if 640 and window position is odd	adc #0	;15-Sep-91 DAL	pha	;X position	lda [RectPtr]	inc a	;Y position	pha	_DrawIcon**********************************************************************		ldy #2	;Y=left	lda #32	;over 6 + 26 for icon size (for 640 mode)	jsr mDrawHalfIf320	;12-Jan-91 DAL	adc [RectPtr],y	;left position of rect	pha	pha	;one more copy 10-Jun-91 DAL	iny	iny	lda [RectPtr],y	;Y=bottom	dec a	dec a	pha	;y coord = bottom - 2	_MoveTo	;set pen to drawing location for first element;	PushZLong atempptr;	_DrawString;*** added 10-Jun-91 DAL -- call DrawStringMaybeCrunch to draw the string;	ldy #6;	lda [RectPtr],y;	sec;	sbc 1,s;	sta 1,s;	pushzlong atempptr;	jsr DrawStringMaybeCrunch;*** end of 10-Jun-91*** 16-Mar-92 DAL -- use DrawStringWidth in QD Aux	plx	;horizontal pen position from above	pea $6000	;truncate on right	pei <atempptr+2	pei <atempptr	phx	ldy #6	lda [RectPtr],y	sec	sbc 1,s	sta 1,s	;available width in pixels	ldx #$1512	jsl $e10000;	_DrawStringWidth*** end 16-Mar-92ItemReturnHook** Return point if a hook was used to draw the items.** now test and see if the item needs to be greyed out.*	ldy #$0004	;flags in the 5th byte	lda [MemberPtr],y	bit #MEM_DISABLE	;if disabled, no selection!	beq NotGrey	;not disabled, could be selected	and #$FF7F	;make sure NEVER selected	sta [MemberPtr],y	;not selected anymore (in case it was!)	PushZPtr oldmask	_GetPenMask	;save old mask	PushLong #GreyMask	_SetPenMask	;set mask to grey	pei RectPtr+2	pei RectPtr	_EraseRect	;grey it out	PushZPtr oldmask	_SetPenMask	;back to normal	bra NotSelectednotGrey	ldy #$0004	lda [MemberPtr],y	and #MEM_SEL	;selected bit	beq NotSelected		pei RectPtr+2	pei RectPtr	_InvertRect	;if selected, invert this memberNotSelected	tsc	clc	adc #0018	tcs	;get rid of atemp and mask and other stuff	plb	pld	lda 1,s	sta 13,s	lda 2,s	sta 14,s	tsc	clc	adc #12	tcs	rtlGreyMask	dc.w $AA55,$AA55	dc.w $AA55,$AA55** mDrawHalfIf320 -- 15-Jan-91 DAL** Cuts A in half if we're in 320 mode** Returns carry clear so we can do an addition right* after the call to this routine.*mDrawHalfIf320	phy	tax	ldy #FGetPutFlag	lda [<TempDPPtr],y	and #$4000	beq @1	;it's 640	txa	lsr a	;cut in half for 320	tax@1	txa	clc	ply	rts;*;* DrawStringMaybeCrunch;*;* push available width;* push pString ptr;* JSR here;*;DrawStringMaybeCrunch;	phd;	tsc;	tcd;	lda [5];	and #$00ff;	cmp #16;	bcc @drawNormal;;	pha	;space for StringWidth;	pei 7;	pei 5;	_StringWidth;	pla;	inc a;	cmp 9;	bcc @drawNormal;;	pha;	pha;	_GetCharExtra;	pea $ffff;	pea $0000;	_SetCharExtra	;negative one;	pei 7;	pei 5;	_DrawString;	_SetCharExtra;	pld;	plx;	pla;	pla;	pla	;stripped input parameters;	phx;	rts;;@drawNormal	pld;	plx;	ply;	pla;	phx;	pha;	phy	;moved RTS addr above String ptr;	_DrawString;	plx;	pla	;kill Width input;	phx;	rts	ENDP	PathDraw	PROC EXPORT************************************************************************ This is the draw routine for the path string in the get and put* dialog as called by a UserItem** Note that since this is called by the window manager that the direct* page and data bank will not be set correctly.** The stack contains the dialog pointer and the item id of the object* pressed but we don't care as this routine is only called in one place.* they will be tossed at exit time.***********************************************************************	phd		;save old direct page	phb	phk	plb		;set data bank to program bank		PushLongSpace		;results	PushWord #0		;system tool	PushWord #$0017		;Standard File tool set	_GetWap	pld		;set DP to old direct page for this routine	pla		;toss upper				jsr DoPathDraw		plb		;restore data bank	pld		;restore direct page	lda 2,s		;restore stack!	sta 8,s	lda 1,s	sta 7,s		;move return address	 	pla	;dialog ptr	pla	pla	;item id			rtl	ENDP************************************************************************ Does the actual clear and draw of the current path. Called by the* above custom useritem draw routine and also by close and open buttons.** ASSUMPTION: (**DEBUG??**) Only the normal system font is used at* this time. Do I need to add code later to determine font size?** Assumptions: It is assumed that PrefixPtr points to the current path* and the curDev contains the current device number. Also that Seperator* contains the current seperation character.***********************************************************************DoPathDraw	PROC EXPORTDrawAreaWidth	equ ztemp2		;in pixelsTextLength	equ ztemp1		;in characters** First determine which dialog box we are using (needs to be changed to a dialog call)*	PushZLong DialogPtr	lda #$0006		;item number for get	bit FGetPutFlag	bpl @1		;correct guess	inc a@1	pha	PushZPtr tempRect	_GetDItemBox	lda tempRect		;top position	clc	adc #03		;move down by 3	sta tempRect	clc	lda tempRect+2		;h position	adc wherex		;dialog position	lsr a		;bottom bit should be set...***	bcs @2		;...for proper color	bcc @2		;15-Mar-91 DAL (previous test seems reversed?)	inc tempRect+2		;force it even!@2	PushZPtr tempRect	_EraseRect		;erase old information	lda FGetPutFlag	bit #InVolumeList		;Check if we're in volume list.	bne @checkWhichDLog		;If we are then display different 	brl notInVolList@checkWhichDLog	bpl getDialog	lda selectedptr+1	bne @SomethingSelected	PushZLong DialogPtr	PushWord #11	_HideDItem@SomethingSelected	lda #255	sta saveButStat	PushWord #255	pha	pha	PushZLong DialogPtr	PushWord #1		;Deactivate SAVE button. 	_GetControlDItem		;It is no longer valid when we're 	_HiliteControl		;displaying the list of volume names.		PushWord #255	pha	pha	PushZLong DialogPtr	PushWord #12		;Deactivate NEWFOLDER button. 	_GetControlDItem		;It's is no longer valid when we're 	_HiliteControl		;displaying the list of volume names.	bra DoSomeMore	getDialog	PushZLong DialogPtr		;If in get dialog hide the prompt string.	PushWord #8	_HideDItemDoSomeMore	PushWord #255	pha	pha	PushZLong DialogPtr	ldy #3	jsr PutAdjust	phy	_GetControlDItem	_HiliteControl		lda tempRect+2		;path string.	pha		;x coordindate	lda tempRect	clc	adc #8	pha		;y coordindate	_MoveTo	PushLong #VolumeString	;display string 'Volumes on-line:'	_DrawString		rts	notInVolList	lda curDev			bne KeepOnTruckin			rts** need to determine which icon to draw here. Either folder, disk, or appletalk or ...*KeepOnTruckin	PushWord #0	pha	pha	PushZLong DialogPtr	ldy #3	jsr PutAdjust	phy	_GetControlDItem	_HiliteControl		bit FGetPutFlag	bmi @notGet		PushZLong DialogPtr		If in get dialog hide the prompt string.	PushWord #8	_ShowDItem	bra @PassPutStuff@notGet	PushZLong DialogPtr	PushWord #11	_ShowDItem@PassPutStuff*** added 18-Dec-91 DAL -- set clip region to path item, leaving old region on stack	PushZLong DialogPtr	lda #$0006		;item number for get	bit FGetPutFlag	bpl @1b		;correct guess	inc a@1b	pha	pushlong #myClipRect	_GetDItemBox	pha	pha	_NewRgn	lda 3,s	pha	lda 3,s	pha		;clone region handle (leave one copy on stack)	_GetClip	pushlong #myClipRect	_ClipRect*** end 18-Dec-91	jsr DrawPopUpThing		;14-Jan-91 DAL*** Padlock-drawing code used to be here	lda tempRect+2	pha	lda tempRect		;top of rect	clc	adc #08		;**DEBUG**Assumes system font always	pha	_MoveTo		;position pen	ldy #2	lda [PrefixPtr],y		;get length of original path	tax		;counter	iny	iny	shortm	lda Seperator		;seperation character@whichloop	iny	dex	cmp [PrefixPtr],y	bne @whichloop		;look for next sep character** Found next seperation character.  Is it as the end of the string?*	longm	dex		;will be 0 if only volume name	bne DoAFolderDoADevice	jsr DoDInfoCall	pha	pha		;space for GetSysIcon result	pea 1		;device icons	lda devDeviceID_DInfo	pha	lda #0	pha	pha		;aux value (long)	_GetSysIcon	ldx #0		;flag: don't increment Y position	bra do_iconDoAFolder	pha	pha		;space for _GetSysIcon result	pea $0004		;file icons (open folder)	pea $000f		;folder	lda #0	pha	pha		;aux value (long)	_GetSysIcon		;fall into do_icon	ldx #1		;flag to increment Y position** do_icon--icon already on stack*do_icon	pea 0		;mode for _DrawIcon	lda #4	jsr HalfIf320	adc <tempRect+2	pha		;X position	clc	txa	adc <tempRect	pha		;Y position	_DrawIcon*** End of Device/Folder icon stuff	lda #30		;move over 30 pixels in 640 mode	jsr HalfIf320		;12-Jan-91 DAL	adc <tempRect+2		;left edge of rect	sta <tempRect+2	pha		;x position	lda <tempRect		;top of rect	clc	adc #8		;**DEBUG**Assumes system font always	pha		;y position	_MoveTo		;position pen** get size in pixels of the drawing rect.*	sec	lda tempRect+6		;right edge	sbc tempRect+2		;right edge - left edge*** 14-Jan-91 DAL -- leave room for the padlock on the right	ldx writeProtect	beq @noWrProt	sbc #16@noWrProt*** end of 14-Jan-91 DAL	sta DrawAreaWidth		;save size to work in ( %%% Dead now??? )*** New pathSeg drawing stuff (15-Jan-91 DAL)	ldy #2	lda [<PrefixPtr],y		;get length of original path	tay	iny	iny	ldx #0	sep #$20	longa off	lda Seperator		;seperation character@findSegLoop	inx	dey	beq @noSegment	cmp [<PrefixPtr],y	bne @findSegLoop		;look for next sep character	iny	longa on	rep #$20*** Set up for DrawText (Y=index to first character to print, X = length)	clc	tya	adc <PrefixPtr	tay	lda <PrefixPtr+2	adc #0	pha	phy	phx	_DrawText@noSegment	rep #$20*** end of new pathSeg drawing stuff	jsr DrawThePadlock		;added 14-Jan-91 DAL	jsr DrawTheFileSystem	;added 25-Mar-91 DAL*** added 18-Dec-91 DAL -- store the right edge of the path item*** [moved below DrawTheFileSystem 6-Feb-92 DAL]	pha	pha		;Pen Loc result buffer	tsc	pea 0	inc a	pha	_GetPen	pla	;y coord	pla	;x coord	sta PathItemRightEdge*** end 18-Dec-91*** added 18-Dec-91 DAL -- restore the clip region	lda 3,s	pha	lda 3,s	pha	;clone my region handle	_SetClip	_DisposeRgn*** end 18-Dec-91	rts;VolumeString	str 'Volumes on-line:'VolumeString	str 'Available disks:'	;25-Mar-92 DAL	export PathItemRightEdgePathItemRightEdge	dc.w 0		;rightmost position to pop up when they click (18-Dec-91 DAL)myClipRect	ds.b 8		;temp rectangle for path item (18-Dec-91 DAL)** DrawPopUpThing -- draw a framed down-arrow to the left of the path item** Location = tempRect (bumps tempRect over, too)*DrawPopUpThing	lda #4	;move over this far in 640 mode	jsr HalfIf320	adc <tempRect+2	sta <tempRect+2	pha	pha	;space for icon	pea 2	;Misc Icons	pea 4	;framed down arrow	lda #0	pha	pha	;aux value (ignored)	_GetSysIcon	;leave icon pointer on stack for DrawIcon	pea 0	;DrawIcon mode	pei <tempRect+2	;X position	pei <tempRect	;Y position	_DrawIcon	lda #24	;move over this far in 640 mode	jsr HalfIf320	adc tempRect+2	sta tempRect+2	rts** Do the Padlock thing*DrawThePadlock	lda writeProtect		;see if a write protected disk	beq @noPadlock	pea 0	tdc	clc	adc #tempRect	pha	_GetPen	lda tempRect+0	;top	sec	sbc #8	sta tempRect+0	pha	pha	;space for GetSysIcon result	pea 2	;misc icons	pea 1	;misc icon #1 = padlock	lda #0	pha	pha	;aux value (long)	_GetSysIcon	pea 0	lda #4	;move over 4 in 640 mode	jsr HalfIf320	adc <tempRect+2	pha	;X	lda <tempRect	inc a	pha	;Y	_DrawIcon	lda #18		;move over this far in 640 mode (was 12 6-Feb-92 DAL)	jsr HalfIf320		;12-Jan-91 DAL*** added 6-Feb-92 DAL -- Also adjust the pen position!	pha	;preserve delta	pha	;delta X for Move	pea 0	;delta Y for Move	_Move	pla	;restore delta*** end 6-Feb-92	adc tempRect+2		;left edge of rect	sta tempRect+2@noPadlock	rts************************************************************************ DrawTheFileSystem -- 25-Mar-91 DAL***********************************************************************DrawTheFileSystem	jsr GetTheFSTName	bcs @notFound	pea $0020	_DrawChar	pea $0028	;'('	_DrawChar	pushlong #fstNameBuffer+4	lda fstNameBuffer+2	and #$00ff	pha	_DrawText	pea $0029	;')'	_DrawChar@notFound	rtsParBlock_FSTInfo	dc.w 5	;pCount=5fstnum_FSTInfo	dc.w 0fstID_FSTInfo	dc.w 0fstName_FSTInfo	dc.l fstNameBufferfstVersion_FSTInfo	dc.w 0fstAttr_FSTInfo	dc.w 0	export fstNameBufferfstNameBuffer	dc.w 32	ds.b 34	export GetTheFSTNameGetTheFSTName	stz fstnum_FSTInfo@search	inc fstnum_FSTInfo	pushlong #ParBlock_FSTInfo	pea $202b	;GetFSTInfo	jsl $e100b0	bcs @notFound	lda fstID_FSTInfo	cmp <FileSysID	bne @search	clc@notFound	rts	ENDP************************************************************************ HalfIf320 -- 12-Jan-91 DAL** Cuts A in half if we're in 320 mode** Returns carry clear so we can do an addition right* after the call to this routine.***********************************************************************HalfIf320	proc export	bit <FGetPutFlag	bvc @1	;it's 640	lsr a	;cut in half for 320@1	clc	rts	EndP************************************************************************ PollForInsertions** Check for a disk insertion and return device number in A if* something was inserted.** The DO_INSERT_SCAN service scans *all* the devices and then tells* us about the first insertion it detected.  This is good for two* things:** 1. We can call PollForInsertion *once* to ignore all pending inserts.* 2. When a CD with multiple partitions is inserted, we only find out*    about it once.***********************************************************************PollForInsertions	proc export	pha	_ScanDevices	pla	rts	EndP************************************************************************ JudgeTheName** Make sure the filename is valid for this file system.  If it's not,* put up a big alert explaining what's wrong.** Return values: CLC = name was okay*                SEC = name was bad, edit line text may or may*                      not have been replaced** Inputs:*   Text in the edit line item (dialog item 10).*   <FileSysID on direct page*   A = 3 for file, 2 for folder***********************************************************************JudgeTheName	proc	import fstNameBuffer	import GetTheFSTName	sta jnNameType	lda <FileSysID	sta jnFileSys	jsr GetTheFSTName;;	pha;;	pha;;	_FrontWindow*** added 18-Dec-91 DAL -- don't use FrontWindow; Bryan P has hidden the window already!	pushzlong <dialogPtr*** end 18-Dec-91	pea 10	;dialog item number for edit line	pushlong #fileName1+1	_GetIText	lda fileName1+1	and #$00ff	sta fileName1	;made it into a GS/OS string	pushlong #fileName1	pushlong #fileName2+2	pushlong #41	_BlockMove	pushlong #JudgeNameParms	pea $2007	jsl $e100b0;	_JudgeName	bcc @noExit	brl @exit@noExit	lda jnNameFlags	clc;;;	beq @nameOK	bne @nameNotOK	brl @nameOK@nameNotOK	lda jnSyntaxString+2	sta theFSTHelpStr+2	lda jnSyntaxString	sta theFSTHelpStr	lda fileName2+2	xba	sta fileName2+2	;make fileName2+3 a Pascal string	lda fileName1	xba	sta fileName1	;make fileName1+1 a Pascal string	lda fstNameBuffer+2	xba	sta fstNameBuffer+2	;make fstNameBuffer+3 a Pascal string	pea $4009	;bad input value, default to bonk	_SysBeep2	_InitCursor	;added 3-Sep-91 DAL	pha	;space for result	pea 5	;by resource, Pascal substitution strings	pushlong #JudgeSubstitutions	pushlong #$07ff1701	;JudgeName alert window ID	_AlertWindow	pla	bcs @exit	sec	beq @exit	;they clicked "No Change"--exit with SEC;;	pha;;	pha;;	_FrontWindow*** 18-Dec-91 DAL	pushzlong <dialogPtr***	pea 10	pushlong #fileName2+3	_SetIText	pha	pha	_FrontWindow	pea 10	pea 0	pea $ff	_SelectIText	sec	;return SEC since their first name was no good@nameOK@exit	rtsJudgeNameParms	dc.w 6	;6 parametersjnFileSys	dc.w 0	;file systemjnNameType	dc.w 0	;name type (1=volume, 2=file, 3=folder, 0=unknown)jnSyntaxString	dc.l 0	;(result) pointer to syntax stringjnMaxLength	dc.w 0	;(result)jnNameBuffer	dc.l fileName2	;input/outputjnNameFlags	dc.w 0	;(result)JudgeSubstitutions	dc.l fileName1+1	; *0 = their trial name	dc.l fstNameBuffer+3 ; *1 = file system name	dc.l fileName2+3	; *2 = fixed-up valid nametheFSTHelpStr	dc.l 0	; *3 = FST-syntax-help message	dc.l noChangeName	; *4 = "No Change"fileName1	ds.b 41fileName2	dc.w 40	;result buffer	ds.b 42noChangeName	dc.b 9,'No Change'	EndP	END 